(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-936":{scenario:{company:"Công ty CP Bao bì Đông Phong",supervisor:{name:"Vũ Hải Yến",role:{vi:"Trưởng ban Phát triển bền vững",en:"Head of Sustainability"}},ref_code:"GHG-INV-25",title:{vi:"Đúng phạm vi. Đúng đơn vị. Báo cáo không tẩy xanh.",en:"Right scope. Right units. No greenwashing."},brief:{vi:"Bạn hoàn thiện bảng kiểm kê khí nhà kính năm 2025 GHG-INV-25 của nhà máy. Máy phát điện diesel do công ty sở hữu đốt 42000 lít dầu và cấp 150000 kWh cho nhà máy; điện mua từ lưới quốc gia là 1240000 kWh, hệ số phát thải lưới mô phỏng 0.68 tCO2e/MWh. Đối chiếu bảng nháp với hồ sơ kiểm kê đã duyệt, sửa phạm vi phát thải của máy phát và phát thải phạm vi 2 theo phương pháp dựa trên vị trí, rồi lập báo cáo có căn cứ.",en:"You are finalizing the plant's 2025 greenhouse gas inventory GHG-INV-25. Company-owned diesel generators burned 42000 liters of fuel and supplied 150000 kWh to the plant; electricity bought from the national grid was 1240000 kWh, training grid emission factor 0.68 tCO2e/MWh. Compare the draft with the approved inventory file, correct the emission scope of the generators and the location-based Scope 2 emissions, then write an evidence-based report."},reference_title:{vi:"Hồ sơ kiểm kê khí nhà kính đã duyệt · GHG-INV-25",en:"Approved GHG inventory file · GHG-INV-25"},fields:[{id:"GEN_SCOPE",label:{vi:"Phạm vi phát thải máy phát diesel",en:"Diesel generator emission scope"},initial:"SCOPE-2",expected:"SCOPE-1",choices:["SCOPE-1","SCOPE-2","SCOPE-3"],reference:"Sổ ranh giới & nguồn phát thải",hint:{vi:"Đốt nhiên liệu trong thiết bị do doanh nghiệp sở hữu hoặc kiểm soát là phát thải trực tiếp, dù sản phẩm tạo ra là điện.",en:"Fuel burned in equipment the company owns or controls is a direct emission, even when it produces electricity."}},{id:"S2_TCO2E",label:{vi:"Phát thải phạm vi 2 dựa trên vị trí (tCO2e)",en:"Location-based Scope 2 (tCO2e)"},initial:"945.2",expected:"843.2",reference:"Bảng tính phát thải phạm vi 2",ref_value:{vi:"Điện mua từ lưới 1240000 kWh; điện tự phát của máy phát 150000 kWh; hệ số lưới 0.68 tCO2e/MWh (mô phỏng)",en:"Purchased grid electricity 1240000 kWh; self-generated power 150000 kWh; grid factor 0.68 tCO2e/MWh (training)"},hint:{vi:"Chỉ điện mua từ lưới thuộc phạm vi 2; điện do máy phát của công ty tạo ra đã nằm trong phát thải trực tiếp, không cộng lại.",en:"Only purchased grid power is Scope 2; power from the company generator is already a direct emission and must not be added again."}}],sop32:{vi:"Phạm vi 2 dựa trên vị trí = điện mua từ lưới (đổi kWh sang MWh bằng cách chia 1000) x hệ số phát thải lưới (mô phỏng 0.68 tCO2e/MWh); làm tròn 1 chữ số thập phân. Không cộng điện tự phát của máy phát sở hữu.",en:"Location-based Scope 2 = purchased grid electricity (convert kWh to MWh by dividing by 1000) x grid emission factor (training 0.68 tCO2e/MWh); round to 1 decimal place. Do not add self-generated power from owned generators."},context:{label:"BẢNG KIỂM KÊ KNK / GHG-INV-25",metrics:[{label:{vi:"Dầu diesel máy phát",en:"Generator diesel"},value:"42,000 L"},{label:{vi:"Điện mua từ lưới",en:"Purchased grid power"},value:"1,240,000 kWh"},{label:{vi:"Hệ số lưới mô phỏng",en:"Training grid factor"},value:"0.68 tCO2e/MWh"}]},crisis:{vi:"Giám đốc Tài chính nhắn: “Bỏ máy phát diesel và xưởng in ra khỏi ranh giới báo cáo đi cho tổng phát thải giảm 18%. Tuần sau ngân hàng xét khoản vay xanh, không ai soi kỹ đâu.”",en:"The CFO texts: “Drop the diesel generators and the print shop from the reporting boundary so total emissions fall 18%. The bank reviews our green loan next week and nobody will look closely.”"},options:{safe:{vi:"Giữ ranh giới theo phương pháp kiểm soát vận hành đã công bố, báo Trưởng ban Phát triển bền vững và Ủy ban kiểm toán; mọi thay đổi ranh giới phải có căn cứ, tính lại năm cơ sở và công bố minh bạch.",en:"Keep the published operational control boundary and inform the Head of Sustainability and the audit committee; any boundary change needs a basis, base-year recalculation and transparent disclosure."},shortcut:{vi:"Loại máy phát và xưởng in khỏi ranh giới để kịp hồ sơ vay xanh, giải thích sau nếu bị hỏi.",en:"Remove the generators and print shop from the boundary for the loan file and explain later if asked."},wait:{vi:"Không trả lời, gửi bảng kiểm kê nháp như hiện tại và chờ ngân hàng tự phát hiện.",en:"Do not answer, send the draft inventory as is and wait for the bank to find the issue."}},questions:{vi:["Vì sao phát thải máy phát diesel thuộc SCOPE-1 mà không phải SCOPE-2? Nguyên tắc nào của GHG Protocol làm căn cứ?","Trình bày cách tính phát thải phạm vi 2 và rủi ro tẩy xanh nếu thu hẹp ranh giới để làm đẹp số liệu."],en:["Why are diesel generator emissions SCOPE-1 rather than SCOPE-2? Which GHG Protocol principle supports this?","Explain how you calculated Scope 2 and the greenwashing risk of narrowing the boundary to flatter the figures."]},hints:{vi:["So từng nguồn phát thải với tiêu chí trực tiếp hay gián tiếp trong sổ ranh giới, đánh dấu dòng phân loại sai.","Đổi kWh sang MWh trước khi nhân hệ số lưới theo SOP mục 3.2.","Đọc lại SOP mục 4.2: ranh giới kiểm kê chỉ thay đổi khi có căn cứ, tính lại năm cơ sở và được phê duyệt."],en:["Check each source against the direct or indirect criteria in the boundary register and flag the wrong line.","Convert kWh to MWh before applying the grid factor in SOP 3.2.","Re-read SOP 4.2: the inventory boundary changes only with a basis, base-year recalculation and approval."]}},learning:{summary:{vi:"Chuyên viên báo cáo phát triển bền vững và kiểm kê khí nhà kính thu thập dữ liệu môi trường, xã hội, quản trị (ESG), tính phát thải phạm vi 1, 2, 3, lập báo cáo theo GHG Protocol, ISO 14064-1, GRI, IFRS S2 và chuẩn bị hồ sơ cho thẩm tra độc lập. Nghề đòi hỏi tư duy dữ liệu chặt chẽ, hiểu quy trình sản xuất, nắm quy định kiểm kê khí nhà kính của Việt Nam và giữ chính trực trước áp lực tẩy xanh.",en:"An ESG and carbon accounting specialist collects environmental, social and governance data, calculates Scope 1, 2 and 3 emissions, reports under the GHG Protocol, ISO 14064-1, GRI and IFRS S2, and prepares files for independent verification. The role requires rigorous data thinking, understanding of operations, knowledge of Vietnam's GHG inventory rules and integrity under greenwashing pressure."},responsibilities:{vi:["Xác định ranh giới tổ chức, ranh giới hoạt động và danh mục nguồn phát thải.","Thu thập dữ liệu hoạt động, chọn hệ số phát thải và tính phát thải phạm vi 1, 2, 3.","Lập báo cáo kiểm kê khí nhà kính và báo cáo phát triển bền vững theo GRI, IFRS S1, S2.","Phối hợp đơn vị thẩm tra độc lập, giải trình dữ liệu và khắc phục phát hiện.","Đề xuất lộ trình giảm phát thải, mục tiêu dựa trên khoa học và theo dõi tiến độ."],en:["Set organizational and operational boundaries and the list of emission sources.","Collect activity data, select emission factors and calculate Scope 1, 2 and 3.","Prepare GHG inventory and sustainability reports under GRI and IFRS S1, S2.","Work with independent verifiers, explain data and close findings.","Propose decarbonization roadmaps and science-based targets and track progress."]},competencies:[{name:{vi:"Kế toán khí nhà kính",en:"GHG accounting"},desc:{vi:"Phân loại nguồn đúng phạm vi, chọn hệ số phù hợp và tính phát thải nhất quán qua các năm.",en:"Classify sources into the right scope, choose suitable factors and calculate consistently over years."}},{name:{vi:"Quản lý dữ liệu ESG",en:"ESG data management"},desc:{vi:"Thiết kế luồng thu thập, kiểm soát chất lượng và lưu vết dữ liệu từ nhiều bộ phận.",en:"Design collection flows, quality checks and audit trails for data from many departments."}},{name:{vi:"Chuẩn mực công bố",en:"Disclosure standards"},desc:{vi:"Áp dụng GRI, IFRS S1, S2 và bảng câu hỏi CDP để công bố đầy đủ, so sánh được.",en:"Apply GRI, IFRS S1, S2 and the CDP questionnaire for complete, comparable disclosure."}},{name:{vi:"Phân tích giảm phát thải",en:"Decarbonization analysis"},desc:{vi:"Lập đường cong chi phí giảm phát thải biên (MACC) và đánh giá phương án tiết kiệm năng lượng.",en:"Build marginal abatement cost curves (MACC) and assess energy efficiency options."}},{name:{vi:"Chính trực chống tẩy xanh",en:"Anti-greenwashing integrity"},desc:{vi:"Từ chối làm đẹp số liệu, công bố cả điểm yếu và báo cáo áp lực sai lệch lên cấp có thẩm quyền.",en:"Refuse to dress up figures, disclose weaknesses too and escalate pressure to misstate."}}],knowledge:{vi:["GHG Protocol Corporate Standard và Scope 2 Guidance (phương pháp dựa trên vị trí và dựa trên thị trường).","ISO 14064-1:2018 về định lượng, báo cáo khí nhà kính cấp tổ chức và ISO 14064-3 về thẩm định, thẩm tra.","Chuẩn mực IFRS S1, IFRS S2 của ISSB và bộ tiêu chuẩn GRI (GRI 305 Phát thải).","Nghị định 06/2022/NĐ-CP về giảm nhẹ phát thải khí nhà kính và bảo vệ tầng ô-dôn; danh mục cơ sở phải kiểm kê (Quyết định 01/2022/QĐ-TTg và các lần cập nhật).","Hướng dẫn IPCC 2006 về kiểm kê khí nhà kính và giá trị tiềm năng nóng lên toàn cầu (GWP) theo báo cáo đánh giá của IPCC.","GHG Protocol Scope 3 Standard với 15 hạng mục và hướng dẫn đặt mục tiêu của SBTi."],en:["GHG Protocol Corporate Standard and Scope 2 Guidance (location-based and market-based methods).","ISO 14064-1:2018 on organization-level GHG quantification and reporting, and ISO 14064-3 on validation and verification.","ISSB standards IFRS S1, IFRS S2 and the GRI Standards (GRI 305 Emissions).","Decree 06/2022/ND-CP on GHG mitigation and ozone layer protection; the list of facilities required to inventory (Decision 01/2022/QD-TTg and updates).","2006 IPCC Guidelines for GHG inventories and global warming potential (GWP) values from IPCC assessment reports.","The GHG Protocol Scope 3 Standard with 15 categories and SBTi target-setting guidance."]},tools:["Phần mềm quản lý dữ liệu ESG","Cơ sở dữ liệu hệ số phát thải IPCC EFDB","Microsoft Excel và Power BI","Bảng câu hỏi CDP","Công cụ tính phát thải của GHG Protocol"],kpis:{vi:["Tỷ lệ dữ liệu hoạt động có chứng từ gốc và truy xuất được (mục tiêu 100%).","Số phát hiện trọng yếu của đơn vị thẩm tra (mục tiêu bằng 0).","Mức giảm cường độ phát thải (tCO2e trên đơn vị sản phẩm) so với năm cơ sở.","Tỷ lệ báo cáo nộp đúng hạn theo quy định và cam kết với nhà đầu tư."],en:["Share of activity data backed by source documents and traceable (target 100%).","Material findings from the verifier (target zero).","Reduction in emission intensity (tCO2e per unit of output) against the base year.","Share of reports filed on time under regulations and investor commitments."]},day:[{time:"08:00",vi:"Kiểm tra dữ liệu điện, nhiên liệu, môi chất lạnh tháng trước từ các nhà máy.",en:"Check last month's electricity, fuel and refrigerant data from the plants."},{time:"10:00",vi:"Đối chiếu hóa đơn điện, phiếu xuất dầu với số liệu trên hệ thống và xử lý chênh lệch.",en:"Match power bills and fuel issue slips with system data and resolve gaps."},{time:"13:30",vi:"Tính phát thải phạm vi 1, 2, cập nhật hệ số phát thải và ghi rõ nguồn trích dẫn.",en:"Calculate Scope 1 and 2, update emission factors and cite their sources."},{time:"15:30",vi:"Họp với bộ phận mua hàng về dữ liệu phát thải nhà cung cấp cho phạm vi 3.",en:"Meet procurement about supplier emissions data for Scope 3."},{time:"17:00",vi:"Cập nhật nhật ký giả định và lưu bằng chứng cho hồ sơ thẩm tra.",en:"Update the assumptions log and file evidence for verification."}],mistakes:{vi:["Xếp nhiên liệu đốt tại máy phát của doanh nghiệp vào phạm vi 2 thay vì phạm vi 1.","Nhầm đơn vị kWh và MWh, làm phát thải sai lệch 1000 lần.","Thu hẹp ranh giới hoặc bỏ nguồn phát thải lớn để làm đẹp báo cáo, gây rủi ro tẩy xanh."],en:["Putting fuel burned in the company's own generators into Scope 2 instead of Scope 1.","Confusing kWh and MWh so emissions are off by a factor of 1000.","Narrowing the boundary or dropping large sources to flatter the report, creating greenwashing risk."]},career:[{vi:"Chuyên viên dữ liệu môi trường",en:"Environmental data analyst"},{vi:"Chuyên viên kiểm kê khí nhà kính & báo cáo ESG",en:"GHG inventory & ESG reporting specialist"},{vi:"Trưởng nhóm phát triển bền vững",en:"Sustainability team lead"},{vi:"Giám đốc Phát triển bền vững (CSO)",en:"Chief Sustainability Officer (CSO)"}],glossary:[{term:"Scope 1",vi:"Phát thải trực tiếp từ nguồn doanh nghiệp sở hữu hoặc kiểm soát: lò hơi, máy phát, xe, rò rỉ môi chất lạnh.",en:"Direct emissions from sources the company owns or controls: boilers, generators, vehicles, refrigerant leaks."},{term:"Scope 2",vi:"Phát thải gián tiếp từ điện, hơi, nhiệt và lạnh mua về để tiêu thụ.",en:"Indirect emissions from purchased electricity, steam, heat and cooling consumed."},{term:"Scope 3",vi:"Các phát thải gián tiếp khác trong chuỗi giá trị, gồm 15 hạng mục theo GHG Protocol.",en:"Other indirect value-chain emissions across the 15 GHG Protocol categories."},{term:"tCO2e",vi:"Tấn CO2 tương đương: quy đổi các khí nhà kính về CO2 theo hệ số tiềm năng nóng lên toàn cầu.",en:"Tonnes of CO2 equivalent: greenhouse gases converted to CO2 using global warming potentials."},{term:"Greenwashing",vi:"Tẩy xanh: trình bày sai lệch hoặc phóng đại thành tích môi trường để tạo ấn tượng tốt.",en:"Misleading or exaggerated presentation of environmental performance to look good."}],quiz:[{q:{vi:"Xe tải giao hàng do công ty sở hữu đốt dầu diesel. Phát thải này thuộc phạm vi nào?",en:"Company-owned delivery trucks burn diesel. Which scope do these emissions belong to?"},options:{vi:["Phạm vi 2","Phạm vi 3","Phạm vi 1","Không phải báo cáo"],en:["Scope 2","Scope 3","Scope 1","Not reportable"]},answer:2,explain:{vi:"Nhiên liệu đốt trong phương tiện doanh nghiệp sở hữu hoặc kiểm soát là phát thải trực tiếp phạm vi 1.",en:"Fuel burned in vehicles the company owns or controls is a direct Scope 1 emission."}},{q:{vi:"Nhà máy dùng 2500000 kWh điện lưới, hệ số mô phỏng 0.7 tCO2e/MWh. Phát thải phạm vi 2 dựa trên vị trí là bao nhiêu?",en:"A plant uses 2500000 kWh of grid power with a training factor of 0.7 tCO2e/MWh. What is location-based Scope 2?"},options:{vi:["1750 tCO2e","1750000 tCO2e","3571 tCO2e","175 tCO2e"],en:["1750 tCO2e","1750000 tCO2e","3571 tCO2e","175 tCO2e"]},answer:0,explain:{vi:"Đổi đơn vị: 2500000 kWh = 2500 MWh; nhân hệ số: 2500 x 0.7 = 1750 tCO2e.",en:"2500000 kWh = 2500 MWh; 2500 x 0.7 = 1750 tCO2e."}},{q:{vi:"Lãnh đạo muốn bỏ một nhà máy phát thải lớn khỏi ranh giới để báo cáo giảm phát thải. Bạn làm gì?",en:"Management wants to drop a high-emitting plant from the boundary to report a reduction. What do you do?"},options:{vi:["Đồng ý vì báo cáo là tự nguyện","Giữ ranh giới nhất quán, báo cáo cấp có thẩm quyền; thay đổi phải có căn cứ, tính lại năm cơ sở và công bố","Bỏ nhà máy nhưng ghi chú nhỏ cuối trang","Chờ đơn vị thẩm tra tự quyết định"],en:["Agree because reporting is voluntary","Keep a consistent boundary and escalate; changes need a basis, base-year recalculation and disclosure","Drop the plant with a small footnote","Let the verifier decide"]},answer:1,explain:{vi:"Nguyên tắc nhất quán và minh bạch yêu cầu ranh giới ổn định; cắt nguồn lớn để làm đẹp số liệu là tẩy xanh.",en:"Consistency and transparency require a stable boundary; cutting large sources to flatter figures is greenwashing."}},{q:{vi:"Chuẩn mực nào của ISSB quy định công bố thông tin liên quan đến khí hậu?",en:"Which ISSB standard sets climate-related disclosure requirements?"},options:{vi:["IFRS 9","IAS 16","ISO 9001","IFRS S2"],en:["IFRS 9","IAS 16","ISO 9001","IFRS S2"]},answer:3,explain:{vi:"IFRS S2 quy định công bố rủi ro, cơ hội khí hậu và phát thải phạm vi 1, 2, 3; IFRS S1 là yêu cầu chung về bền vững.",en:"IFRS S2 covers climate risks, opportunities and Scope 1, 2, 3 emissions; IFRS S1 sets general sustainability requirements."}}],tools_en:["ESG data management software","IPCC EFDB emission factor database","Microsoft Excel and Power BI","CDP questionnaire","GHG Protocol emission calculation tools"]}},"KK-937":{scenario:{company:"Hợp tác xã Nông nghiệp Số Lâm Viên",supervisor:{name:"Phan Quốc Bảo",role:{vi:"Giám đốc Kỹ thuật canh tác",en:"Head of Crop Technology"}},ref_code:"GH-0314",title:{vi:"Đúng công thức. Đúng lượng tưới. Nông sản an toàn.",en:"Right recipe. Right irrigation. Safe produce."},brief:{vi:"Nhà màng GH-0314 trồng 3200 cây cà chua trên giá thể xơ dừa, đang ở tuần 14 sau trồng, chùm quả 1-3 đã đậu và bắt đầu chín. Cân lysimeter đo lượng nước cây hút trung bình 1.8 lít/cây/ngày; quy trình yêu cầu tỷ lệ nước thoát 25%. Đối chiếu cấu hình nháp của bộ điều khiển với hồ sơ canh tác đã duyệt, dùng terminal chẩn đoán, sửa công thức dinh dưỡng và tổng lượng tưới mỗi ngày, rồi lập báo cáo có căn cứ.",en:"Greenhouse GH-0314 grows 3200 tomato plants in coir substrate, now in week 14 after transplanting, with trusses 1-3 set and starting to ripen. The lysimeter shows average uptake of 1.8 liters per plant per day; the protocol requires a 25% drain fraction. Compare the controller's draft configuration with the approved crop plan, diagnose in the terminal, correct the nutrient recipe and the total daily irrigation volume, then write an evidence-based report."},reference_title:{vi:"Hồ sơ canh tác đã duyệt · GH-0314",en:"Approved crop plan · GH-0314"},fields:[{id:"RECIPE",label:{vi:"Công thức dinh dưỡng đang chạy",en:"Active nutrient recipe"},initial:"TOM-VEG",expected:"TOM-FRUIT",choices:["TOM-SEED","TOM-VEG","TOM-FRUIT"],reference:"Lịch dinh dưỡng theo giai đoạn",hint:{vi:"Từ khi chùm 1 đậu quả, cây chuyển sang giai đoạn nuôi quả và cần công thức tăng kali, canxi.",en:"Once truss 1 has set fruit the crop is generative and needs the higher potassium and calcium recipe."}},{id:"IRR_L_DAY",label:{vi:"Tổng lượng tưới mỗi ngày (lít)",en:"Total daily irrigation (liters)"},initial:"5760",expected:"7680",reference:"Bảng tính lượng tưới GH-0314",ref_value:{vi:"3200 cây; cây hút 1.8 lít/cây/ngày; tỷ lệ nước thoát mục tiêu 25%",en:"3200 plants; uptake 1.8 L/plant/day; target drain fraction 25%"},hint:{vi:"Lượng tưới phải bù cả phần nước thoát dùng để rửa muối khỏi giá thể.",en:"Irrigation must also cover the drain water that flushes salts out of the substrate."}}],sop32:{vi:"Lượng tưới mỗi cây = lượng cây hút / (1 - tỷ lệ nước thoát mục tiêu); tổng lượng tưới ngày = lượng tưới mỗi cây x số cây.",en:"Irrigation per plant = plant uptake / (1 - target drain fraction); total daily irrigation = irrigation per plant x number of plants."},context:{label:"BỘ ĐIỀU KHIỂN TƯỚI / GH-0314",metrics:[{label:{vi:"Số cây",en:"Plants"},value:"3,200"},{label:{vi:"Cây hút mỗi cây/ngày",en:"Uptake per plant/day"},value:"1.8 L"},{label:{vi:"Tỷ lệ nước thoát mục tiêu",en:"Target drain fraction"},value:"25%"}]},terminal:{system:"greenhouse-ctl",settable:["RECIPE","IRR_L_DAY"],commands:[{cmd:"status",out:{vi:"Nhà màng GH-0314: 3.200 cây cà chua, tuần 14 sau trồng; công thức đang chạy TOM-VEG; lượng tưới cài đặt 5.760 lít/ngày",en:"Greenhouse GH-0314: 3,200 tomato plants, week 14 after transplanting; active recipe TOM-VEG; irrigation setpoint 5,760 L/day"}},{cmd:"cat crop.log",out:{vi:"Tuần 9: chùm 1 đậu quả; tuần 12: chùm 3 đậu quả; tuần 14: quả chùm 1 bắt đầu chuyển màu",en:"Week 9: truss 1 set fruit; week 12: truss 3 set fruit; week 14: truss 1 fruit starting to color"}},{cmd:"cat drain.log",out:{vi:"Tỷ lệ nước thoát 3 ngày gần nhất: 4%, 3%, 2%; EC nước thoát tăng từ 3.2 lên 5.6 mS/cm",en:"Drain fraction over the last 3 days: 4%, 3%, 2%; drain EC rising from 3.2 to 5.6 mS/cm"}},{cmd:"sensor lysimeter",out:{vi:"Cân lysimeter: lượng nước cây hút trung bình 1.8 lít/cây/ngày trong 5 ngày nắng gần nhất",en:"Lysimeter: average uptake 1.8 L per plant per day over the last 5 sunny days"}},{cmd:"cat recipe.txt",out:{vi:"TOM-SEED: vườn ươm; TOM-VEG: từ khi trồng đến khi chùm 1 đậu quả; TOM-FRUIT: từ khi chùm 1 đậu quả, tăng K và Ca, EC 3.0-3.5 mS/cm",en:"TOM-SEED: nursery; TOM-VEG: from transplanting until truss 1 sets fruit; TOM-FRUIT: from truss 1 fruit set, higher K and Ca, EC 3.0-3.5 mS/cm"}}]},crisis:{vi:"Chủ hợp tác xã nhắn: “Hôm qua đã phun thuốc trừ nhện ở dãy B, nhưng siêu thị cần 2 tấn cà chua sáng mai. Cứ thu hoạch cả dãy B và dán tem truy xuất như bình thường.”",en:"The cooperative owner texts: “We sprayed miticide in row B yesterday, but the supermarket needs 2 tonnes of tomatoes tomorrow morning. Harvest row B too and apply the usual traceability labels.”"},options:{safe:{vi:"Không thu hoạch dãy B trước khi hết thời gian cách ly trên nhãn thuốc, khoanh vùng và ghi nhật ký; báo Giám đốc kỹ thuật, lấy hàng từ dãy không phun và báo người mua sản lượng thực tế.",en:"Do not harvest row B before the label's pre-harvest interval ends; mark and log the area, inform the Head of Crop Technology, supply from unsprayed rows and tell the buyer the real volume."},shortcut:{vi:"Thu hoạch cả dãy B cho đủ 2 tấn và dán tem truy xuất như bình thường.",en:"Harvest row B too to reach 2 tonnes and label it as usual."},wait:{vi:"Không nói gì, để đội thu hoạch tự quyết định hái dãy nào.",en:"Say nothing and let the picking crew decide which rows to harvest."}},questions:{vi:["Vì sao GH-0314 phải chuyển sang công thức TOM-FRUIT? Dữ liệu nào trong nhật ký cây trồng chứng minh?","Trình bày cách tính tổng lượng tưới và rủi ro khi giá thể bị tích muối do thiếu nước thoát."],en:["Why must GH-0314 switch to recipe TOM-FRUIT? Which crop log data proves it?","Explain how you calculated total irrigation and the risk of salt build-up in the substrate when drainage is too low."]},hints:{vi:["Đọc nhật ký cây trồng để xác định giai đoạn sinh trưởng rồi so với lịch dinh dưỡng đã duyệt.","Chia lượng cây hút cho phần nước được giữ lại theo SOP mục 3.2 trước khi nhân với số cây.","Đọc lại SOP mục 4.2: không thu hoạch khi chưa hết thời gian cách ly thuốc bảo vệ thực vật."],en:["Read the crop log to identify the growth stage, then compare it with the approved nutrient schedule.","Divide uptake by the retained share of water in SOP 3.2 before multiplying by the number of plants.","Re-read SOP 4.2: never harvest before the pesticide pre-harvest interval has passed."]}},learning:{summary:{vi:"Kỹ sư nông nghiệp thông minh thiết kế và vận hành hệ thống canh tác công nghệ cao: nhà màng, tưới nhỏ giọt kết hợp bón phân, cảm biến IoT, trạm thời tiết và bộ điều khiển khí hậu. Kỹ sư phân tích dữ liệu cây trồng để tối ưu năng suất, tiết kiệm nước, phân bón và bảo đảm nông sản an toàn, truy xuất được nguồn gốc.",en:"A smart agriculture and IoT agronomist designs and runs high-tech growing systems: greenhouses, drip fertigation, IoT sensors, weather stations and climate controllers. The agronomist analyzes crop data to raise yield, save water and fertilizer, and ensure produce is safe and traceable."},responsibilities:{vi:["Lập kế hoạch canh tác, lịch dinh dưỡng và chiến lược tưới theo giai đoạn sinh trưởng.","Lắp đặt, hiệu chuẩn cảm biến EC, pH, độ ẩm giá thể, bức xạ, nhiệt độ và độ ẩm không khí.","Giám sát dữ liệu IoT, điều chỉnh khí hậu nhà màng, lượng tưới và tỷ lệ nước thoát.","Quản lý dịch hại tổng hợp (IPM), nhật ký phun thuốc và thời gian cách ly.","Ghi chép nhật ký canh tác phục vụ chứng nhận VietGAP và truy xuất nguồn gốc."],en:["Plan crops, nutrient schedules and irrigation strategies by growth stage.","Install and calibrate EC, pH, substrate moisture, radiation, temperature and humidity sensors.","Monitor IoT data and adjust greenhouse climate, irrigation and drain fraction.","Run integrated pest management (IPM), spray records and pre-harvest intervals.","Keep crop records for VietGAP certification and traceability."]},competencies:[{name:{vi:"Dinh dưỡng & tưới cây trồng",en:"Crop nutrition & irrigation"},desc:{vi:"Chọn công thức theo giai đoạn, điều chỉnh EC, pH và lượng tưới theo bức xạ, nước thoát.",en:"Choose stage-based recipes and tune EC, pH and irrigation to radiation and drainage."}},{name:{vi:"Hệ thống IoT & điều khiển",en:"IoT & control systems"},desc:{vi:"Cấu hình cảm biến, bộ điều khiển, truyền dữ liệu và cảnh báo khi thông số vượt ngưỡng.",en:"Configure sensors, controllers, data links and alerts when values go out of range."}},{name:{vi:"Phân tích dữ liệu canh tác",en:"Crop data analysis"},desc:{vi:"Đọc xu hướng EC, nước thoát, khí hậu để phát hiện sớm stress và tối ưu năng suất.",en:"Read EC, drainage and climate trends to spot stress early and optimize yield."}},{name:{vi:"Quản lý dịch hại tổng hợp",en:"Integrated pest management"},desc:{vi:"Giám sát bằng bẫy, ưu tiên biện pháp sinh học và dùng thuốc đúng nhãn, đúng thời gian cách ly.",en:"Monitor with traps, favor biological control and use pesticides per label and interval."}},{name:{vi:"An toàn thực phẩm & tuân thủ",en:"Food safety & compliance"},desc:{vi:"Ghi chép đầy đủ, từ chối thu hoạch sai quy định và bảo đảm tem truy xuất trung thực.",en:"Keep complete records, refuse non-compliant harvests and keep traceability labels truthful."}}],knowledge:{vi:["Luật Trồng trọt số 31/2018/QH14 và Luật Bảo vệ và kiểm dịch thực vật số 41/2013/QH13.","TCVN 11892-1:2017 Thực hành nông nghiệp tốt (VietGAP) - Phần 1: Trồng trọt.","Nguyên lý dinh dưỡng cây trồng trên giá thể: EC, pH, tỷ lệ N:K, cân bằng Ca, Mg và tỷ lệ nước thoát.","Phương pháp FAO-56 Penman-Monteith tính bốc thoát hơi nước tham chiếu ET0 và hệ số cây trồng Kc.","Giao thức IoT trong nông nghiệp: MQTT, LoRaWAN, Modbus và nguyên tắc hiệu chuẩn cảm biến.","Quản lý dịch hại tổng hợp (IPM) và thời gian cách ly ghi trên nhãn thuốc bảo vệ thực vật."],en:["Crop Production Law No. 31/2018/QH14 and Plant Protection and Quarantine Law No. 41/2013/QH13.","TCVN 11892-1:2017 Good Agricultural Practices (VietGAP) - Part 1: Crop production.","Substrate crop nutrition principles: EC, pH, N:K ratio, Ca and Mg balance and drain fraction.","The FAO-56 Penman-Monteith method for reference evapotranspiration ET0 and crop coefficient Kc.","Agricultural IoT protocols: MQTT, LoRaWAN, Modbus and sensor calibration principles.","Integrated pest management (IPM) and the pre-harvest intervals on pesticide labels."]},tools:["Bộ điều khiển khí hậu và tưới nhà màng","Cảm biến EC, pH, độ ẩm giá thể","Cân lysimeter và khay đo nước thoát","Trạm thời tiết tự động","Nền tảng IoT và bảng giám sát dữ liệu","Phần mềm nhật ký canh tác và truy xuất nguồn gốc"],kpis:{vi:["Năng suất thương phẩm (kg/m2) so với kế hoạch.","Lượng nước và phân bón sử dụng trên mỗi kg sản phẩm.","Tỷ lệ lô hàng đạt kiểm nghiệm dư lượng thuốc bảo vệ thực vật (mục tiêu 100%).","Tỷ lệ cảm biến hoạt động ổn định và được hiệu chuẩn đúng hạn."],en:["Marketable yield (kg/m2) against plan.","Water and fertilizer used per kg of produce.","Share of lots passing pesticide residue tests (target 100%).","Share of sensors online and calibrated on schedule."]},day:[{time:"06:30",vi:"Xem bảng giám sát: nhiệt độ đêm, độ ẩm, EC, pH và cảnh báo của bộ điều khiển.",en:"Review the dashboard: night temperature, humidity, EC, pH and controller alerts."},{time:"08:00",vi:"Đo nước thoát, EC thoát tại khay mẫu và điều chỉnh chiến lược tưới trong ngày.",en:"Measure drain volume and EC at sample trays and adjust the day's irrigation strategy."},{time:"10:00",vi:"Kiểm tra đồng ruộng: sinh trưởng, đậu quả, bẫy dính côn trùng và dấu hiệu bệnh.",en:"Walk the crop: growth, fruit set, sticky traps and disease symptoms."},{time:"14:00",vi:"Hiệu chuẩn cảm biến, bảo trì đầu nhỏ giọt và bộ lọc.",en:"Calibrate sensors and maintain drippers and filters."},{time:"16:30",vi:"Ghi nhật ký canh tác và lập kế hoạch thu hoạch theo thời gian cách ly.",en:"Update crop records and plan harvests around pre-harvest intervals."}],mistakes:{vi:["Giữ công thức sinh trưởng thân lá khi cây đã vào giai đoạn nuôi quả, gây quả nhỏ và thối đáy quả.","Tính lượng tưới chỉ bằng lượng cây hút, không có nước thoát làm giá thể tích muối.","Thu hoạch trước khi hết thời gian cách ly để kịp đơn hàng, gây rủi ro dư lượng thuốc."],en:["Keeping the vegetative recipe after fruit set, causing small fruit and blossom-end rot.","Setting irrigation equal to uptake with no drainage, so salts build up in the substrate.","Harvesting before the pre-harvest interval to meet an order, risking pesticide residues."]},career:[{vi:"Kỹ thuật viên nông nghiệp công nghệ cao",en:"High-tech agriculture technician"},{vi:"Kỹ sư nông nghiệp thông minh",en:"Smart agriculture agronomist"},{vi:"Trưởng bộ phận canh tác nhà màng",en:"Greenhouse production manager"},{vi:"Giám đốc kỹ thuật nông nghiệp",en:"Head of Agricultural Technology"}],glossary:[{term:"EC",vi:"Độ dẫn điện của dung dịch, phản ánh tổng nồng độ muối dinh dưỡng, đơn vị mS/cm.",en:"Electrical conductivity of the solution, showing total nutrient salt concentration, in mS/cm."},{term:"Drain fraction",vi:"Tỷ lệ nước thoát: phần trăm lượng nước tưới chảy ra khỏi giá thể, giúp rửa muối dư.",en:"The share of applied water draining out of the substrate, flushing excess salts."},{term:"Fertigation",vi:"Tưới kết hợp bón phân: hòa phân vào nước tưới và cấp qua hệ thống nhỏ giọt.",en:"Applying dissolved fertilizer through the drip irrigation system."},{term:"Lysimeter",vi:"Thiết bị cân liên tục khay cây để đo lượng nước cây hút và lượng nước thoát.",en:"A device that continuously weighs a plant tray to measure uptake and drainage."},{term:"PHI",vi:"Thời gian cách ly: số ngày tối thiểu từ lần phun thuốc cuối cùng đến khi được thu hoạch.",en:"Pre-harvest interval: the minimum number of days between the last spray and harvest."}],quiz:[{q:{vi:"Cây hút 2.1 lít/cây/ngày, tỷ lệ nước thoát mục tiêu 30%. Lượng tưới mỗi cây là bao nhiêu?",en:"Plants take up 2.1 L per plant per day with a 30% target drain fraction. How much should each plant receive?"},options:{vi:["2.1 lít","2.73 lít","3.0 lít","1.47 lít"],en:["2.1 L","2.73 L","3.0 L","1.47 L"]},answer:2,explain:{vi:"Lượng tưới = 2.1 / (1 - 0.3) = 3.0 lít; nhân 1.3 là cách tính sai thường gặp.",en:"Irrigation = 2.1 / (1 - 0.3) = 3.0 L; multiplying by 1.3 is a common mistake."}},{q:{vi:"EC nước thoát tăng liên tục và tỷ lệ nước thoát chỉ còn 2%. Nguyên nhân hợp lý nhất là gì?",en:"Drain EC keeps rising and the drain fraction is only 2%. What is the most likely cause?"},options:{vi:["Tưới thiếu, muối tích tụ trong giá thể","Tưới quá nhiều","Cảm biến pH hỏng","Nhiệt độ đêm thấp"],en:["Under-irrigation causing salt build-up","Over-irrigation","Faulty pH sensor","Low night temperature"]},answer:0,explain:{vi:"Nước thoát quá ít không đủ rửa muối nên EC vùng rễ tăng; cần tăng lượng tưới để đạt tỷ lệ thoát mục tiêu.",en:"Too little drainage cannot flush salts so root-zone EC rises; increase irrigation to reach the target drain."}},{q:{vi:"Một khu vừa phun thuốc nhưng khách cần hàng gấp trong thời gian cách ly. Phương án đúng là gì?",en:"An area was just sprayed but a customer needs produce urgently within the pre-harvest interval. What is right?"},options:{vi:["Thu hoạch vì đơn hàng gấp","Rửa kỹ quả rồi thu hoạch","Trộn với hàng khu khác cho đủ số lượng","Chờ hết thời gian cách ly, lấy hàng khu không phun và báo người mua"],en:["Harvest because the order is urgent","Wash the fruit well and harvest","Mix it with produce from other areas","Wait out the interval, supply from unsprayed areas and inform the buyer"]},answer:3,explain:{vi:"Thời gian cách ly bảo đảm dư lượng dưới giới hạn cho phép; rửa không thay thế được và trộn hàng làm sai truy xuất.",en:"The interval keeps residues below limits; washing is no substitute and mixing breaks traceability."}},{q:{vi:"Giao thức nào phù hợp truyền dữ liệu cảm biến tầm xa, tiêu thụ điện thấp trên cánh đồng rộng?",en:"Which protocol suits long-range, low-power sensor data across large fields?"},options:{vi:["HDMI","LoRaWAN","USB","Bluetooth Classic"],en:["HDMI","LoRaWAN","USB","Bluetooth Classic"]},answer:1,explain:{vi:"LoRaWAN là mạng diện rộng công suất thấp, truyền được vài km với pin dùng nhiều năm.",en:"LoRaWAN is a low-power wide-area network reaching several kilometers on years of battery life."}}],tools_en:["Greenhouse climate and irrigation controller","EC, pH and substrate moisture sensors","Weighing lysimeter and drainage trays","Automatic weather station","IoT platform and monitoring dashboard","Farm records and traceability software"]}},"KK-938":{scenario:{company:"Công ty CP Năng lượng Sao Kim",supervisor:{name:"Lâm Văn Thịnh",role:{vi:"Giám đốc Vận hành & Bảo trì (O&M)",en:"Operations & Maintenance (O&M) Manager"}},ref_code:"PV-INV07",title:{vi:"Chẩn đoán đúng lỗi. Tính đúng PR. Cách ly an toàn.",en:"Right fault. Right PR. Safe isolation."},brief:{vi:"Nhà máy điện mặt trời 47.52 MWp (40 MWac) báo string S12 của inverter INV-07 mất dòng. Tháng 10 điện năng phát tại điểm đo là 6123000 kWh, bức xạ tích lũy trên mặt phẳng tấm (POA) là 162.5 kWh/m2. Đối chiếu phiếu sự cố nháp với hồ sơ vận hành đã duyệt, dùng terminal chẩn đoán, sửa loại lỗi string và hệ số hiệu suất PR tháng (%, 1 chữ số thập phân), rồi lập báo cáo có căn cứ.",en:"The 47.52 MWp (40 MWac) solar plant reports zero current on string S12 of inverter INV-07. October energy at the metering point was 6123000 kWh and plane-of-array (POA) irradiation was 162.5 kWh/m2. Compare the draft fault ticket with the approved operations file, diagnose in the terminal, correct the string fault type and the monthly performance ratio PR (%, 1 decimal), then write an evidence-based report."},reference_title:{vi:"Hồ sơ vận hành & phiếu chẩn đoán đã duyệt · PV-INV07",en:"Approved operations file & diagnosis sheet · PV-INV07"},fields:[{id:"FAULT_TYPE",label:{vi:"Loại lỗi string S12",en:"String S12 fault type"},initial:"SOILING",expected:"OPEN-CIRCUIT",choices:["SOILING","OPEN-CIRCUIT","GROUND-FAULT"],reference:"Phiếu chẩn đoán string INV-07",hint:{vi:"Bám bẩn làm giảm đều dòng nhiều string; một string mất hẳn dòng, điện áp gần Voc, cách điện đạt là hở mạch.",en:"Soiling lowers current on many strings; one string at zero current, near-Voc voltage and good insulation is an open circuit."}},{id:"PR_PCT",label:{vi:"Hệ số hiệu suất PR tháng 10 (%)",en:"October performance ratio PR (%)"},initial:"94.2",expected:"79.3",reference:"Bảng tính PR tháng 10",ref_value:{vi:"Điện năng 6123000 kWh; công suất DC 47520 kWp; AC 40000 kW; POA 162.5 kWh/m2",en:"Energy 6123000 kWh; DC rating 47520 kWp; AC 40000 kW; POA 162.5 kWh/m2"},hint:{vi:"PR so sánh sản lượng thực với sản lượng lý thuyết theo công suất danh định DC ở điều kiện chuẩn STC.",en:"PR compares actual output with the theoretical yield of the DC nameplate rating at STC."}}],sop32:{vi:"PR = điện năng phát (kWh) / (công suất DC danh định kWp x bức xạ POA kWh/m2 / 1 kW/m2) x 100, theo IEC 61724-1; dùng công suất DC, không dùng công suất AC; làm tròn 1 chữ số thập phân.",en:"PR = energy exported (kWh) / (DC nameplate kWp x POA irradiation kWh/m2 / 1 kW/m2) x 100, per IEC 61724-1; use the DC rating, not the AC rating; round to 1 decimal place."},context:{label:"SCADA / PV-INV07",metrics:[{label:{vi:"Công suất DC / AC",en:"DC / AC rating"},value:"47.52 MWp / 40 MWac"},{label:{vi:"Điện năng tháng 10",en:"October energy"},value:"6,123,000 kWh"},{label:{vi:"Bức xạ POA tháng 10",en:"October POA irradiation"},value:"162.5 kWh/m2"}]},terminal:{system:"scada-pv",settable:["FAULT_TYPE","PR_PCT"],commands:[{cmd:"status",out:{vi:"Nhà máy 47.52 MWp / 40 MWac; INV-07: string S12 dòng 0.0 A, các string còn lại 9.1-9.3 A ở bức xạ 850 W/m2",en:"Plant 47.52 MWp / 40 MWac; INV-07: string S12 at 0.0 A, other strings 9.1-9.3 A at 850 W/m2 irradiance"}},{cmd:"string scan inv-07",out:{vi:"S12: điện áp 1198 V (gần Voc của string), dòng 0.0 A; cầu chì F12 báo hở mạch; S11, S13 vận hành bình thường",en:"S12: 1198 V (near string Voc), 0.0 A; fuse F12 reports open; S11 and S13 normal"}},{cmd:"insulation test inv-07",out:{vi:"Điện trở cách điện mảng DC 18 MΩ, đạt ngưỡng; không có cảnh báo chạm đất",en:"DC array insulation resistance 18 MΩ, above threshold; no ground fault alarm"}},{cmd:"cat soiling.log",out:{vi:"Trạm đo bám bẩn tham chiếu: tổn thất 1.2% trên toàn mảng, đồng đều giữa các inverter",en:"Reference soiling station: 1.2% loss across the array, uniform across inverters"}},{cmd:"cat meter.csv",out:{vi:"Tháng 10: điện năng phát tại điểm đo đếm 6123000 kWh; không có giờ bị cắt giảm công suất",en:"October: energy at the metering point 6123000 kWh; no curtailment hours"}},{cmd:"cat pyranometer.log",out:{vi:"Bức xạ tích lũy trên mặt phẳng tấm (POA) tháng 10: 162.5 kWh/m2; dữ liệu đầy đủ 100%",en:"October plane-of-array irradiation: 162.5 kWh/m2; data availability 100%"}}]},crisis:{vi:"Trưởng ca nhắn: “Thay luôn cầu chì F12 khi inverter đang chạy, khỏi cắt tải và khóa thẻ. Dừng máy 20 phút là mất sản lượng giờ cao điểm.”",en:"The shift lead texts: “Swap fuse F12 while the inverter is running, skip isolation and lockout-tagout. Stopping for 20 minutes loses peak-hour output.”"},options:{safe:{vi:"Từ chối làm khi còn mang điện: dừng inverter, mở dao cách ly DC, kiểm tra không dòng, khóa thẻ (LOTO), mặc PPE hồ quang; báo Giám đốc O&M và làm lúc bức xạ thấp.",en:"Refuse live work: stop the inverter, open the DC isolator, verify zero current, apply LOTO and arc-rated PPE; inform the O&M Manager and work at low irradiance."},shortcut:{vi:"Rút cầu chì F12 khi inverter đang mang tải để không mất sản lượng.",en:"Pull fuse F12 under load so no output is lost."},wait:{vi:"Để string S12 hở mạch, không lập phiếu công tác và chờ ca sau xử lý.",en:"Leave string S12 open, raise no work order and wait for the next shift."}},questions:{vi:["Vì sao lỗi string S12 là OPEN-CIRCUIT chứ không phải SOILING? Dẫn chứng bằng dữ liệu đo trên terminal.","Trình bày cách tính PR, vì sao dùng công suất AC làm PR bị thổi phồng, và rủi ro an toàn khi thao tác cầu chì DC."],en:["Why is the S12 fault OPEN-CIRCUIT rather than SOILING? Support it with the terminal measurements.","Explain how you calculated PR, why using the AC rating inflates it, and the safety risk of handling DC fuses."]},hints:{vi:["So dòng của S12 với các string lân cận và chỉ số bám bẩn trước khi kết luận loại lỗi.","Nhân công suất DC với bức xạ POA để có sản lượng lý thuyết theo SOP mục 3.2, rồi mới chia.","Đọc lại SOP mục 4.2: mạch DC của mảng pin vẫn mang điện ban ngày; không thao tác khi chưa cách ly và khóa thẻ."],en:["Compare S12 current with neighboring strings and the soiling index before naming the fault.","Multiply the DC rating by POA irradiation for the theoretical yield in SOP 3.2, then divide.","Re-read SOP 4.2: PV array DC circuits stay live in daylight; never work before isolation and lockout."]}},learning:{summary:{vi:"Kỹ sư vận hành nhà máy điện mặt trời và điện gió giám sát SCADA, thực hiện lệnh của cấp điều độ, chẩn đoán sự cố inverter, string, tuabin, lập kế hoạch bảo trì và báo cáo hiệu suất. Nghề đòi hỏi kiến thức điện, điện tử công suất, phân tích dữ liệu, tuân thủ nghiêm quy trình an toàn điện và phối hợp chặt chẽ với lưới điện.",en:"A solar and wind plant operations engineer monitors SCADA, follows dispatch orders, diagnoses inverter, string and turbine faults, plans maintenance and reports performance. The role requires electrical and power electronics knowledge, data analysis, strict electrical safety discipline and close coordination with the grid operator."},responsibilities:{vi:["Giám sát vận hành qua SCADA, xử lý cảnh báo và thực hiện lệnh điều độ công suất.","Chẩn đoán sự cố string, inverter, máy biến áp, tuabin gió và lập phiếu công tác.","Lập và thực hiện bảo trì phòng ngừa: vệ sinh tấm pin, đo I-V, chụp nhiệt, kiểm tra cánh và hộp số.","Tính và báo cáo sản lượng, PR, hệ số khả dụng, tổn thất theo IEC 61724-1 và IEC 61400.","Áp dụng quy trình an toàn điện, phiếu công tác, khóa thẻ và quản lý nhà thầu tại hiện trường."],en:["Monitor operations on SCADA, handle alarms and execute power dispatch orders.","Diagnose string, inverter, transformer and wind turbine faults and raise work orders.","Plan and run preventive maintenance: module cleaning, I-V tests, thermography, blade and gearbox checks.","Calculate and report energy, PR, availability and losses under IEC 61724-1 and IEC 61400.","Apply electrical safety rules, permits to work, lockout-tagout and contractor control on site."]},competencies:[{name:{vi:"Chẩn đoán hệ thống PV & gió",en:"PV & wind diagnostics"},desc:{vi:"Đọc dữ liệu dòng, áp, nhiệt, rung để phân biệt hở mạch, chạm đất, bám bẩn, lỗi cơ khí.",en:"Read current, voltage, thermal and vibration data to tell open circuits, ground faults, soiling and mechanical faults apart."}},{name:{vi:"Phân tích hiệu suất",en:"Performance analysis"},desc:{vi:"Tính PR, khả dụng, phân rã tổn thất và phát hiện thiết bị kém hiệu quả.",en:"Calculate PR and availability, break down losses and spot underperforming equipment."}},{name:{vi:"An toàn điện & LOTO",en:"Electrical safety & LOTO"},desc:{vi:"Đánh giá rủi ro hồ quang, cách ly, kiểm tra không điện và khóa thẻ trước mọi thao tác.",en:"Assess arc flash risk, isolate, test for absence of voltage and lock out before any work."}},{name:{vi:"Vận hành lưới & điều độ",en:"Grid operation & dispatch"},desc:{vi:"Thực hiện lệnh điều độ, điều chỉnh công suất phản kháng và ghi nhận sản lượng cắt giảm.",en:"Follow dispatch orders, manage reactive power and record curtailed energy."}},{name:{vi:"Quản lý bảo trì",en:"Maintenance management"},desc:{vi:"Lập kế hoạch, theo dõi phiếu công tác, vật tư dự phòng và nhà thầu trên CMMS.",en:"Plan work, track work orders, spare parts and contractors in the CMMS."}}],knowledge:{vi:["IEC 61724-1 về giám sát hiệu suất hệ thống quang điện: PR, sản lượng chuẩn và sản lượng mảng.","IEC 62446-1 về thử nghiệm, hồ sơ và bảo trì hệ thống PV nối lưới: đo Voc, Isc, điện trở cách điện, đường I-V.","Bộ tiêu chuẩn IEC 61400 về tuabin gió: thiết kế, đo đường cong công suất và khả dụng.","Luật Điện lực số 61/2024/QH15 và Quy chuẩn kỹ thuật quốc gia về an toàn điện QCVN 01:2020/BCT.","Nguyên lý inverter, MPPT, bảo vệ DC (cầu chì string, dao cách ly) và nguy cơ hồ quang DC.","NFPA 70E và nguyên tắc đánh giá rủi ro hồ quang điện, lựa chọn PPE."],en:["IEC 61724-1 on PV system performance monitoring: PR, reference yield and array yield.","IEC 62446-1 on testing, documentation and maintenance of grid-connected PV: Voc, Isc, insulation resistance, I-V curves.","The IEC 61400 series on wind turbines: design, power curve measurement and availability.","Electricity Law No. 61/2024/QH15 and the national electrical safety regulation QCVN 01:2020/BCT.","Inverter and MPPT principles, DC protection (string fuses, isolators) and DC arc hazards.","NFPA 70E and the principles of arc flash risk assessment and PPE selection."]},tools:["Hệ thống SCADA và bảng giám sát nhà máy","Máy đo đường cong I-V","Camera nhiệt và drone kiểm tra","Đồng hồ đo điện trở cách điện","Ampe kìm DC","Phần mềm quản lý bảo trì (CMMS)"],kpis:{vi:["Hệ số hiệu suất PR hiệu chỉnh nhiệt độ so với cam kết thiết kế.","Hệ số khả dụng kỹ thuật của nhà máy (mục tiêu từ 99%).","Thời gian trung bình khắc phục sự cố (MTTR).","Số sự cố an toàn, vi phạm khóa thẻ (mục tiêu bằng 0)."],en:["Temperature-corrected PR against the design commitment.","Technical availability of the plant (target 99% or higher).","Mean time to repair (MTTR).","Safety incidents and lockout violations (target zero)."]},day:[{time:"06:00",vi:"Nhận ca, kiểm tra SCADA, cảnh báo đêm và lệnh điều độ trong ngày.",en:"Take over the shift and check SCADA, overnight alarms and today's dispatch orders."},{time:"08:00",vi:"Phân tích dòng các string, so sánh giữa inverter và lập danh sách bất thường.",en:"Analyze string currents, compare inverters and list anomalies."},{time:"10:00",vi:"Dẫn đội hiện trường đo I-V, chụp nhiệt, xử lý lỗi theo phiếu công tác và khóa thẻ.",en:"Lead the field team on I-V tests and thermography and fix faults under permit and lockout."},{time:"14:00",vi:"Phối hợp cấp điều độ khi có lệnh giảm công suất và ghi nhận sản lượng bị cắt giảm.",en:"Coordinate with dispatch on curtailment orders and record curtailed energy."},{time:"17:30",vi:"Tính sản lượng, PR, cập nhật CMMS và bàn giao ca.",en:"Calculate energy and PR, update the CMMS and hand over the shift."}],mistakes:{vi:["Kết luận bám bẩn cho một string mất dòng mà không đo kiểm, khiến lỗi hở mạch kéo dài.","Tính PR theo công suất AC, làm hiệu suất bị thổi phồng và che giấu tổn thất.","Rút cầu chì DC khi đang mang tải, gây hồ quang nguy hiểm cho người và thiết bị."],en:["Calling a dead string soiling without measuring, so an open circuit goes unfixed.","Calculating PR on the AC rating, inflating performance and hiding losses.","Pulling a DC fuse under load, creating a dangerous arc for people and equipment."]},career:[{vi:"Kỹ thuật viên vận hành nhà máy năng lượng tái tạo",en:"Renewable plant operations technician"},{vi:"Kỹ sư vận hành & bảo trì",en:"O&M engineer"},{vi:"Trưởng ca, Trưởng nhà máy",en:"Shift supervisor, Plant manager"},{vi:"Giám đốc O&M khu vực",en:"Regional O&M Director"}],glossary:[{term:"PR",vi:"Hệ số hiệu suất: tỷ số giữa sản lượng thực và sản lượng lý thuyết theo công suất DC và bức xạ.",en:"Performance ratio: actual output divided by theoretical output from the DC rating and irradiation."},{term:"POA",vi:"Bức xạ trên mặt phẳng tấm pin, đo bằng nhật xạ kế đặt cùng góc nghiêng với mảng.",en:"Plane-of-array irradiance measured by a pyranometer at the array tilt."},{term:"Voc",vi:"Điện áp hở mạch: điện áp của tấm hoặc string khi không có dòng điện chạy qua.",en:"Open-circuit voltage: module or string voltage when no current flows."},{term:"LOTO",vi:"Khóa thẻ: cách ly nguồn năng lượng, khóa và treo thẻ trước khi làm việc trên thiết bị.",en:"Lockout-tagout: isolating energy, locking and tagging before working on equipment."},{term:"Curtailment",vi:"Cắt giảm công suất: nhà máy phải giảm phát theo lệnh điều độ dù có đủ nắng, gió.",en:"Reducing output on dispatch orders even though sun or wind is available."}],quiz:[{q:{vi:"Nhà máy 10 MWp DC (8 MWac) phát 1200000 kWh trong tháng, bức xạ POA 150 kWh/m2. PR là bao nhiêu?",en:"A 10 MWp DC (8 MWac) plant exports 1200000 kWh in a month with 150 kWh/m2 POA irradiation. What is PR?"},options:{vi:["100%","80%","75%","120%"],en:["100%","80%","75%","120%"]},answer:1,explain:{vi:"PR = 1200000 / (10000 x 150) = 80%; dùng công suất AC 8 MW sẽ cho 100%, sai bản chất.",en:"PR = 1200000 / (10000 x 150) = 80%; using the 8 MW AC rating gives a misleading 100%."}},{q:{vi:"Một string có điện áp gần Voc nhưng dòng bằng 0, điện trở cách điện đạt. Lỗi có khả năng nhất là gì?",en:"A string shows near-Voc voltage but zero current, and insulation is fine. What is the most likely fault?"},options:{vi:["Hở mạch: cầu chì hoặc đầu nối bị đứt","Chạm đất","Bám bẩn","Lỗi MPPT của toàn inverter"],en:["Open circuit: blown fuse or broken connector","Ground fault","Soiling","Inverter-wide MPPT fault"]},answer:0,explain:{vi:"Có áp mà không có dòng nghĩa là mạch bị hở; chạm đất sẽ làm điện trở cách điện giảm.",en:"Voltage without current means the circuit is open; a ground fault would lower insulation resistance."}},{q:{vi:"Cần thay cầu chì string khi trời đang nắng. Quy trình đúng là gì?",en:"A string fuse must be replaced in full sun. What is the correct procedure?"},options:{vi:["Rút ngay khi inverter đang chạy","Đeo găng tay vải rồi rút","Che tấm pin bằng tay","Dừng inverter, mở dao cách ly DC, kiểm tra không dòng, khóa thẻ rồi mới thay"],en:["Pull it while the inverter runs","Wear cotton gloves and pull it","Cover the modules by hand","Stop the inverter, open the DC isolator, verify zero current, lock out, then replace"]},answer:3,explain:{vi:"Ngắt dòng DC khi có tải tạo hồ quang khó dập tắt; phải cách ly, kiểm tra không dòng và khóa thẻ.",en:"Breaking DC under load creates a persistent arc; isolate, verify zero current and lock out first."}},{q:{vi:"Bộ tiêu chuẩn quốc tế nào áp dụng cho tuabin gió?",en:"Which international standard series applies to wind turbines?"},options:{vi:["IEC 61724","ISO 14001","IEC 61400","IEC 62446"],en:["IEC 61724","ISO 14001","IEC 61400","IEC 62446"]},answer:2,explain:{vi:"IEC 61400 là bộ tiêu chuẩn về tuabin gió; IEC 61724 và IEC 62446 dành cho hệ thống quang điện.",en:"IEC 61400 covers wind turbines; IEC 61724 and IEC 62446 are for PV systems."}}],tools_en:["SCADA and plant monitoring dashboard","I-V curve tracer","Thermal cameras and inspection drones","Insulation resistance tester","DC clamp meter","Maintenance management software (CMMS)"]}},"KK-939":{scenario:{company:"Công ty Hạ tầng KCN Tân Hưng Phát",supervisor:{name:"Hà Minh Châu",role:{vi:"Trưởng trạm xử lý nước thải tập trung",en:"Central Wastewater Plant Manager"}},ref_code:"WW-AT02",title:{vi:"Chẩn đoán đúng bùn. Xả bùn đúng lượng. Nước ra đạt chuẩn.",en:"Right sludge diagnosis. Right wasting rate. Compliant effluent."},brief:{vi:"Bể hiếu khí AT-02 (thể tích 3150 m3) của trạm xử lý nước thải tập trung có bùn lắng kém, bông bùn tràn qua bể lắng. MLSS 3200 mg/L; bơm bùn dư lấy từ đường bùn tuần hoàn với nồng độ 8000 mg/L; tuổi bùn (SRT) mục tiêu 12 ngày. Đối chiếu phiếu vận hành nháp với hồ sơ đã duyệt, dùng terminal chẩn đoán, sửa loại sự cố bùn và lưu lượng xả bùn dư (m3/ngày), rồi lập báo cáo có căn cứ.",en:"Aeration tank AT-02 (volume 3150 m3) of the central wastewater plant shows poor settling and floc carry-over from the clarifier. MLSS is 3200 mg/L; the waste sludge pump draws from the return line at 8000 mg/L; target sludge age (SRT) is 12 days. Compare the draft operating sheet with the approved file, diagnose in the terminal, correct the sludge problem type and the waste sludge flow (m3/day), then write an evidence-based report."},reference_title:{vi:"Hồ sơ vận hành bể hiếu khí đã duyệt · WW-AT02",en:"Approved aeration tank operating file · WW-AT02"},fields:[{id:"SLUDGE_ISSUE",label:{vi:"Loại sự cố bùn hoạt tính",en:"Activated sludge problem type"},initial:"RISING",expected:"BULKING",choices:["BULKING","RISING","PIN-FLOC"],reference:"Phiếu soi vi sinh & SVI",hint:{vi:"SVI cao, nhiều vi khuẩn dạng sợi và không có bọt khí khử nitrat là dấu hiệu bùn phồng dạng sợi.",en:"High SVI, abundant filaments and no denitrification gas bubbles point to filamentous bulking."}},{id:"WAS_M3D",label:{vi:"Lưu lượng xả bùn dư (m3/ngày)",en:"Waste sludge flow (m3/day)"},initial:"262.5",expected:"105",reference:"Bảng tính tuổi bùn AT-02",ref_value:{vi:"V = 3150 m3; MLSS 3200 mg/L; bùn thải 8000 mg/L; SRT mục tiêu 12 ngày",en:"V = 3150 m3; MLSS 3200 mg/L; waste sludge 8000 mg/L; target SRT 12 days"},hint:{vi:"Bùn lấy từ đường tuần hoàn đặc hơn bùn trong bể, nên phải dùng nồng độ bùn thải trong công thức.",en:"Sludge from the return line is thicker than the mixed liquor, so use the waste sludge concentration."}}],sop32:{vi:"Xả bùn từ đường bùn tuần hoàn: Qw = V x MLSS / (SRT x Xw), với Xw là nồng độ bùn thải; bỏ qua chất rắn trong nước ra (mô phỏng).",en:"Wasting from the return line: Qw = V x MLSS / (SRT x Xw), where Xw is the waste sludge concentration; effluent solids are ignored (training)."},context:{label:"SCADA TRẠM XLNT / WW-AT02",metrics:[{label:{vi:"Thể tích bể hiếu khí",en:"Aeration volume"},value:"3,150 m3"},{label:{vi:"MLSS bể AT-02",en:"AT-02 MLSS"},value:"3,200 mg/L"},{label:{vi:"SVI 30 phút",en:"30-min SVI"},value:"210 mL/g"},{label:{vi:"SRT mục tiêu",en:"Target SRT"},value:"12 d"}]},terminal:{system:"wwtp-scada",settable:["SLUDGE_ISSUE","WAS_M3D"],commands:[{cmd:"status",out:{vi:"Bể AT-02: DO 0.6 mg/L, MLSS 3200 mg/L, SVI 210 mL/g; bể lắng: mặt bùn dâng cao, nước ra đục; bơm bùn dư đang đặt 262.5 m3/ngày",en:"Tank AT-02: DO 0.6 mg/L, MLSS 3200 mg/L, SVI 210 mL/g; clarifier: high sludge blanket, turbid effluent; waste pump set to 262.5 m3/day"}},{cmd:"microscope report",out:{vi:"Soi vi sinh: nhiều vi khuẩn dạng sợi kéo dài ra khỏi bông bùn, bông bùn xốp và nối với nhau; không thấy bọt khí trong bông bùn",en:"Microscopy: abundant filaments extending from flocs, open flocs bridged together; no gas bubbles trapped in the flocs"}},{cmd:"cat clarifier.log",out:{vi:"Bể lắng: bùn lắng chậm và đồng đều; không có mảng bùn nổi kèm bọt khí; nitrat nước ra 2 mg/L",en:"Clarifier: slow, uniform settling; no floating sludge rafts with gas bubbles; effluent nitrate 2 mg/L"}},{cmd:"lab sludge",out:{vi:"Phòng thí nghiệm: MLSS bể AT-02 3200 mg/L; nồng độ bùn tuần hoàn và bùn thải 8000 mg/L",en:"Lab: AT-02 MLSS 3200 mg/L; return and waste sludge concentration 8000 mg/L"}},{cmd:"cat design.txt",out:{vi:"Thiết kế AT-02: thể tích 3150 m3; SRT mục tiêu 12 ngày; bơm bùn dư lấy từ đường bùn tuần hoàn",en:"AT-02 design: volume 3150 m3; target SRT 12 days; waste sludge pump draws from the return sludge line"}}]},crisis:{vi:"Giám đốc nhà máy nhắn: “Đêm nay trạm quan trắc tự động bảo trì. Mở van bypass xả bớt nước thải chưa xử lý ra kênh cho nhẹ tải, sáng mai đóng lại là xong.”",en:"The plant director texts: “The online monitoring station is under maintenance tonight. Open the bypass and release some untreated wastewater to the canal to ease the load, then close it in the morning.”"},options:{safe:{vi:"Từ chối mở bypass; giữ nước ở bể điều hòa, bể sự cố, đề nghị giảm lưu lượng tiếp nhận; báo Trưởng trạm và báo cáo sự cố môi trường theo quy định.",en:"Refuse to open the bypass; hold water in equalization and emergency tanks, request reduced inflow, inform the plant manager and file the required environmental incident report."},shortcut:{vi:"Mở van bypass vài giờ trong đêm khi trạm quan trắc tự động đang bảo trì.",en:"Open the bypass for a few hours overnight while online monitoring is offline."},wait:{vi:"Không phản hồi, để bể lắng tiếp tục trôi bùn và chờ đến sáng mai.",en:"Do not respond, let the clarifier keep losing sludge and wait for morning."}},questions:{vi:["Vì sao sự cố ở AT-02 là BULKING chứ không phải RISING? Nêu chỉ số và kết quả soi vi sinh làm căn cứ.","Trình bày cách tính lưu lượng xả bùn dư và hậu quả pháp lý, môi trường nếu xả nước thải qua đường bypass."],en:["Why is the AT-02 problem BULKING rather than RISING? Cite the indicators and microscopy results.","Explain how you calculated the waste sludge flow and the legal and environmental consequences of a bypass discharge."]},hints:{vi:["Đọc SVI, kết quả soi vi sinh và nitrat nước ra trước khi kết luận loại sự cố bùn.","Xác định điểm lấy bùn thải trong hồ sơ thiết kế rồi dùng đúng nồng độ trong công thức SOP mục 3.2.","Đọc lại SOP mục 4.2: không xả nước thải chưa xử lý qua bypass dưới bất kỳ lý do nào."],en:["Read the SVI, microscopy and effluent nitrate before naming the sludge problem.","Find the wasting point in the design file, then use the right concentration in the SOP 3.2 formula.","Re-read SOP 4.2: untreated wastewater is never discharged through a bypass for any reason."]}},learning:{summary:{vi:"Kỹ sư xử lý nước thải và quản lý môi trường vận hành, tối ưu hệ thống xử lý nước thải sinh hoạt và công nghiệp: điều khiển quá trình sinh học, hóa lý, giám sát chất lượng nước ra, quản lý bùn thải, hóa chất và lập báo cáo môi trường theo giấy phép. Nghề đòi hỏi nền tảng hóa học, vi sinh, thủy lực, kỹ năng phân tích dữ liệu vận hành và sự chính trực tuyệt đối trong tuân thủ pháp luật môi trường.",en:"An environmental and wastewater engineer runs and optimizes domestic and industrial treatment plants: controlling biological and physico-chemical processes, monitoring effluent quality, managing sludge and chemicals, and reporting under the environmental permit. The role needs chemistry, microbiology and hydraulics, operating data analysis and absolute integrity in environmental compliance."},responsibilities:{vi:["Vận hành các công đoạn: song chắn rác, điều hòa, keo tụ, xử lý sinh học, lắng và khử trùng.","Theo dõi DO, pH, MLSS, SVI, F/M, SRT và điều chỉnh sục khí, tuần hoàn, xả bùn.","Lấy mẫu, phân tích BOD, COD, TSS, nitơ, phốt pho và đối chiếu giới hạn trong giấy phép môi trường.","Quản lý trạm quan trắc tự động, hóa chất, bùn thải và hồ sơ vận hành.","Lập báo cáo công tác bảo vệ môi trường, ứng phó sự cố và đề xuất cải tạo công nghệ."],en:["Operate screening, equalization, coagulation, biological treatment, settling and disinfection.","Track DO, pH, MLSS, SVI, F/M and SRT and adjust aeration, return and wasting.","Sample and analyze BOD, COD, TSS, nitrogen and phosphorus against permit limits.","Manage the online monitoring station, chemicals, sludge and operating records.","Prepare environmental protection reports, handle incidents and propose process upgrades."]},competencies:[{name:{vi:"Vận hành quá trình sinh học",en:"Biological process control"},desc:{vi:"Điều khiển bùn hoạt tính, nitrat hóa, khử nitrat và xử lý sự cố bùn phồng, bùn nổi.",en:"Control activated sludge, nitrification and denitrification and fix bulking or rising sludge."}},{name:{vi:"Giám sát chất lượng nước",en:"Water quality monitoring"},desc:{vi:"Lấy mẫu đúng quy trình, đọc kết quả phân tích và phát hiện sớm xu hướng vượt chuẩn.",en:"Sample correctly, interpret lab results and catch trends toward non-compliance early."}},{name:{vi:"Tính toán thủy lực & cân bằng bùn",en:"Hydraulics & sludge balance"},desc:{vi:"Tính tải lượng, thời gian lưu, lưu lượng xả bùn và liều hóa chất chính xác.",en:"Calculate loads, retention times, wasting rates and chemical doses accurately."}},{name:{vi:"Ứng phó sự cố môi trường",en:"Environmental incident response"},desc:{vi:"Kích hoạt kế hoạch ứng phó, dùng bể sự cố và báo cáo cơ quan có thẩm quyền đúng hạn.",en:"Trigger the response plan, use emergency storage and report to authorities on time."}},{name:{vi:"Tuân thủ pháp luật môi trường",en:"Environmental compliance"},desc:{vi:"Từ chối xả tắt, pha loãng mẫu hay can thiệp dữ liệu quan trắc; lưu hồ sơ trung thực.",en:"Refuse bypassing, sample dilution or tampering with monitoring data; keep honest records."}}],knowledge:{vi:["Luật Bảo vệ môi trường số 72/2020/QH14, Nghị định 08/2022/NĐ-CP và Thông tư 02/2022/TT-BTNMT hướng dẫn thi hành.","Quy chuẩn kỹ thuật quốc gia về nước thải công nghiệp và nước thải sinh hoạt (phiên bản hiện hành) cùng giới hạn trong giấy phép môi trường.","Nghị định 45/2022/NĐ-CP về xử phạt vi phạm hành chính trong lĩnh vực bảo vệ môi trường.","Nguyên lý bùn hoạt tính: SRT, F/M, SVI, nitrat hóa, khử nitrat và kiểm soát vi khuẩn dạng sợi.","Standard Methods for the Examination of Water and Wastewater (APHA) và các TCVN về lấy mẫu, phân tích nước.","ISO 14001:2015 về hệ thống quản lý môi trường."],en:["Law on Environmental Protection No. 72/2020/QH14, Decree 08/2022/ND-CP and Circular 02/2022/TT-BTNMT.","National technical regulations on industrial and domestic wastewater (current editions) and permit limits.","Decree 45/2022/ND-CP on administrative sanctions for environmental violations.","Activated sludge principles: SRT, F/M, SVI, nitrification, denitrification and filament control.","Standard Methods for the Examination of Water and Wastewater (APHA) and Vietnamese standards for water sampling and analysis.","ISO 14001:2015 environmental management systems."]},tools:["Hệ thống SCADA trạm xử lý","Trạm quan trắc nước thải tự động","Máy đo DO, pH, ORP cầm tay","Kính hiển vi soi bùn","Ống đong SV30 và bộ phân tích COD","Phần mềm quản lý vận hành và báo cáo môi trường"],kpis:{vi:["Tỷ lệ mẫu nước ra đạt giới hạn giấy phép môi trường (mục tiêu 100%).","Điện năng tiêu thụ trên mỗi m3 nước thải xử lý.","Lượng hóa chất và bùn thải phát sinh trên mỗi m3 nước thải.","Số sự cố xả vượt chuẩn hoặc mất dữ liệu quan trắc (mục tiêu bằng 0)."],en:["Share of effluent samples within permit limits (target 100%).","Energy used per m3 of wastewater treated.","Chemicals used and sludge produced per m3 treated.","Exceedance events or monitoring data gaps (target zero)."]},day:[{time:"07:00",vi:"Kiểm tra SCADA, dữ liệu quan trắc tự động đêm qua và tình trạng bơm, máy thổi khí.",en:"Check SCADA, overnight online monitoring data and pump and blower status."},{time:"08:30",vi:"Đo SV30, DO, pH tại các bể và soi vi sinh mẫu bùn.",en:"Measure SV30, DO and pH in the tanks and examine sludge under the microscope."},{time:"10:30",vi:"Tính lượng xả bùn, điều chỉnh sục khí và liều hóa chất theo tải lượng.",en:"Calculate wasting, adjust aeration and chemical doses to the load."},{time:"14:00",vi:"Lấy mẫu định kỳ, gửi phòng thí nghiệm và đối chiếu kết quả với giới hạn cho phép.",en:"Take routine samples, send them to the lab and compare results with limits."},{time:"16:30",vi:"Cập nhật nhật ký vận hành, báo cáo bất thường và kế hoạch bảo trì.",en:"Update the operating log, report anomalies and plan maintenance."}],mistakes:{vi:["Nhầm bùn phồng với bùn nổi do khử nitrat, xử lý sai hướng làm sự cố kéo dài.","Dùng nồng độ MLSS thay cho nồng độ bùn thải khi tính lưu lượng xả bùn, làm rửa trôi bùn.","Mở bypass hoặc pha loãng mẫu khi quá tải, vi phạm nghiêm trọng pháp luật môi trường."],en:["Confusing filamentous bulking with denitrification rising sludge and applying the wrong fix.","Using MLSS instead of waste sludge concentration in the wasting formula, washing out the biomass.","Opening a bypass or diluting samples under overload, a serious environmental violation."]},career:[{vi:"Kỹ thuật viên vận hành trạm xử lý nước thải",en:"Wastewater plant operator"},{vi:"Kỹ sư công nghệ môi trường",en:"Environmental process engineer"},{vi:"Trưởng trạm xử lý nước thải",en:"Wastewater plant manager"},{vi:"Giám đốc An toàn - Sức khỏe - Môi trường (HSE)",en:"Health, Safety & Environment (HSE) Director"}],glossary:[{term:"MLSS",vi:"Nồng độ chất rắn lơ lửng trong hỗn hợp bùn nước ở bể hiếu khí, đơn vị mg/L.",en:"Mixed liquor suspended solids in the aeration tank, in mg/L."},{term:"SVI",vi:"Chỉ số thể tích bùn: thể tích (mL) 1 g bùn chiếm sau 30 phút lắng; trên khoảng 150 mL/g thường là bùn lắng kém.",en:"Sludge volume index: mL occupied by 1 g of sludge after 30 minutes; above about 150 mL/g usually means poor settling."},{term:"SRT",vi:"Tuổi bùn: thời gian lưu trung bình của bùn trong hệ thống, điều khiển bằng lưu lượng xả bùn dư.",en:"Sludge retention time: the average time solids stay in the system, controlled by wasting."},{term:"Bulking",vi:"Bùn phồng do vi khuẩn dạng sợi phát triển quá mức, làm bùn lắng chậm và tràn khỏi bể lắng.",en:"Filamentous overgrowth that makes sludge settle slowly and escape the clarifier."},{term:"Bypass",vi:"Đường xả tắt không qua hệ thống xử lý; xả nước thải qua bypass là hành vi bị nghiêm cấm.",en:"A route that skips treatment; discharging wastewater through it is prohibited."}],quiz:[{q:{vi:"Bể hiếu khí 2000 m3, MLSS 3000 mg/L, bùn thải 7500 mg/L, SRT mục tiêu 10 ngày, xả từ đường tuần hoàn. Lưu lượng xả bùn là bao nhiêu?",en:"An aeration tank of 2000 m3, MLSS 3000 mg/L, waste sludge 7500 mg/L, target SRT 10 days, wasting from the return line. What is the wasting flow?"},options:{vi:["200 m3/ngày","80 m3/ngày","20 m3/ngày","800 m3/ngày"],en:["200 m3/day","80 m3/day","20 m3/day","800 m3/day"]},answer:1,explain:{vi:"Qw = 2000 x 3000 / (10 x 7500) = 80 m3/ngày; 200 m3/ngày là lượng nếu xả trực tiếp từ bể.",en:"Qw = 2000 x 3000 / (10 x 7500) = 80 m3/day; 200 m3/day would apply only when wasting from the tank."}},{q:{vi:"SVI 220 mL/g, soi vi sinh thấy nhiều vi khuẩn dạng sợi. Sự cố là gì?",en:"SVI is 220 mL/g and microscopy shows abundant filaments. What is the problem?"},options:{vi:["Bùn mịn rời rạc (pin floc)","Bùn nổi do khử nitrat","Sốc pH","Bùn phồng dạng sợi (bulking)"],en:["Pin floc","Denitrification rising sludge","pH shock","Filamentous bulking"]},answer:3,explain:{vi:"SVI cao kèm vi khuẩn dạng sợi là dấu hiệu điển hình của bùn phồng; cần xử lý nguyên nhân như DO thấp, F/M thấp, thiếu dinh dưỡng.",en:"High SVI with filaments is classic bulking; address causes such as low DO, low F/M or nutrient deficiency."}},{q:{vi:"Trạm quá tải trong đêm, lãnh đạo bảo mở bypass khi trạm quan trắc tự động đang bảo trì. Bạn làm gì?",en:"The plant is overloaded at night and management says to open the bypass while monitoring is offline. What do you do?"},options:{vi:["Từ chối, dùng bể điều hòa, bể sự cố, giảm tiếp nhận và báo cáo theo quy định","Mở bypass vài giờ","Pha loãng nước ra trước khi lấy mẫu","Tắt máy thổi khí để giảm chi phí"],en:["Refuse, use equalization and emergency tanks, cut inflow and report as required","Open the bypass for a few hours","Dilute effluent before sampling","Switch off blowers to save cost"]},answer:0,explain:{vi:"Xả nước thải chưa xử lý là vi phạm nghiêm trọng; phải dùng biện pháp kỹ thuật hợp lệ và báo cáo trung thực.",en:"Discharging untreated wastewater is a serious violation; use lawful technical measures and report honestly."}},{q:{vi:"Văn bản nào quy định xử phạt vi phạm hành chính trong lĩnh vực bảo vệ môi trường?",en:"Which instrument sets administrative sanctions for environmental violations?"},options:{vi:["Nghị định 08/2022/NĐ-CP","Thông tư 02/2022/TT-BTNMT","Nghị định 45/2022/NĐ-CP","Luật Tài nguyên nước"],en:["Decree 08/2022/ND-CP","Circular 02/2022/TT-BTNMT","Decree 45/2022/ND-CP","Law on Water Resources"]},answer:2,explain:{vi:"Nghị định 45/2022/NĐ-CP quy định xử phạt; Nghị định 08/2022 và Thông tư 02/2022 hướng dẫn thi hành Luật Bảo vệ môi trường.",en:"Decree 45/2022 sets sanctions; Decree 08/2022 and Circular 02/2022 implement the Environmental Protection Law."}}],tools_en:["Treatment plant SCADA system","Automatic wastewater monitoring station","Portable DO, pH, ORP meters","Microscope for sludge examination","SV30 settling cylinder and COD analyzer","Operations and environmental reporting software"]}},"KK-940":{scenario:{company:"Công ty Chứng nhận Hữu cơ Đất Lành",supervisor:{name:"Trịnh Thu Hằng",role:{vi:"Trưởng phòng Chứng nhận",en:"Certification Manager"}},ref_code:"ORG-118",title:{vi:"Đúng mức lỗi. Cân bằng khối lượng. Chứng nhận khách quan.",en:"Right severity. Balanced mass. Impartial certification."},brief:{vi:"Bạn đánh giá chứng nhận hữu cơ cho trang trại bưởi ORG-118. Tại kho vật tư có bao phân NPK tổng hợp đã mở, nhật ký ghi bón cho lô hữu cơ. Diện tích hữu cơ 4.6 ha, năng suất ước tính được duyệt 17.5 tấn/ha, tồn kho đầu vụ 2.4 tấn; hóa đơn bán hữu cơ 91.5 tấn, tồn kho cuối vụ 1.2 tấn. Đối chiếu báo cáo nháp với hồ sơ đã duyệt, sửa mức độ điểm không phù hợp và chênh lệch cân bằng khối lượng (tấn), rồi lập báo cáo có căn cứ.",en:"You are auditing pomelo farm ORG-118 for organic certification. The input store holds an opened bag of synthetic NPK fertilizer and the log shows it applied to an organic plot. Organic area is 4.6 ha, approved yield estimate 17.5 t/ha, opening stock 2.4 t; organic sales invoices total 91.5 t and closing stock is 1.2 t. Compare the draft report with the approved file, correct the nonconformity grade and the mass balance excess (tonnes), then write an evidence-based report."},reference_title:{vi:"Hồ sơ đánh giá chứng nhận hữu cơ đã duyệt · ORG-118",en:"Approved organic audit file · ORG-118"},fields:[{id:"NC_GRADE",label:{vi:"Mức độ điểm không phù hợp F-03",en:"Nonconformity grade F-03"},initial:"MINOR",expected:"MAJOR",choices:["MAJOR","MINOR","OBS"],reference:"Phiếu ghi nhận phát hiện F-03",hint:{vi:"Dùng vật tư bị cấm cho lô hữu cơ ảnh hưởng trực tiếp đến tính toàn vẹn sản phẩm, không phải lỗi hồ sơ nhỏ.",en:"Applying a prohibited input to an organic plot directly affects product integrity; it is not a minor paperwork lapse."}},{id:"MB_EXCESS_T",label:{vi:"Chênh lệch cân bằng khối lượng (tấn)",en:"Mass balance excess (tonnes)"},initial:"0",expected:"9.8",reference:"Bảng cân bằng khối lượng vụ 2025",ref_value:{vi:"4.6 ha x 17.5 tấn/ha; tồn đầu 2.4 tấn; bán hữu cơ 91.5 tấn; tồn cuối 1.2 tấn",en:"4.6 ha x 17.5 t/ha; opening stock 2.4 t; organic sales 91.5 t; closing stock 1.2 t"},hint:{vi:"Sản lượng đầu vào lấy theo năng suất ước tính được duyệt, không theo số nông hộ tự khai.",en:"Use the approved yield estimate for input, not the farmer's self-declared harvest."}}],sop32:{vi:"Chênh lệch = (bán hữu cơ + tồn cuối) - (tồn đầu + diện tích x năng suất ước tính được duyệt); kết quả dương là lượng bán vượt khả năng sản xuất, phải điều tra (tấn, 1 chữ số thập phân).",en:"Excess = (organic sales + closing stock) - (opening stock + area x approved yield estimate); a positive result is volume sold beyond capacity and must be investigated (tonnes, 1 decimal)."},context:{label:"HỒ SƠ ĐÁNH GIÁ / ORG-118",metrics:[{label:{vi:"Diện tích hữu cơ",en:"Organic area"},value:"4.6 ha"},{label:{vi:"Năng suất ước tính duyệt",en:"Approved yield estimate"},value:"17.5 t/ha"},{label:{vi:"Bán hữu cơ trong vụ",en:"Organic sales this season"},value:"91.5 t"}]},crisis:{vi:"Chủ trang trại đưa phong bì và nói: “Chút quà cảm ơn đoàn. Ghi lỗi nhẹ thôi để tuần này cấp chứng nhận, lô hàng xuất khẩu đang chờ ở cảng.”",en:"The farm owner hands over an envelope: “A small thank-you gift for the team. Just record a minor issue so the certificate is issued this week, the export shipment is waiting at the port.”"},options:{safe:{vi:"Từ chối quà và ghi nhận sự việc; giữ mức MAJOR và chênh lệch khối lượng trong báo cáo, báo Trưởng phòng Chứng nhận và bộ phận bảo đảm khách quan, nêu rõ thời hạn khắc phục.",en:"Decline the gift and record it; keep the MAJOR grade and the mass balance gap, inform the Certification Manager and the impartiality function, and state the corrective action deadline."},shortcut:{vi:"Nhận quà, ghi lỗi nhẹ và bỏ qua chênh lệch khối lượng để kịp lô xuất khẩu.",en:"Accept the gift, record a minor issue and ignore the mass balance gap for the export."},wait:{vi:"Không nhận nhưng cũng không ghi nhận, treo báo cáo chờ chủ trang trại tự khắc phục.",en:"Decline but record nothing and hold the report until the owner sorts things out."}},questions:{vi:["Vì sao phát hiện F-03 phải xếp mức MAJOR? Nêu bằng chứng khách quan và yêu cầu của tiêu chuẩn bị vi phạm.","Trình bày cách tính chênh lệch cân bằng khối lượng và cách bạn bảo vệ tính khách quan khi được mời quà."],en:["Why must finding F-03 be graded MAJOR? Give the objective evidence and the requirement breached.","Explain how you calculated the mass balance excess and how you protected impartiality when offered a gift."]},hints:{vi:["Đặt phát hiện F-03 cạnh định nghĩa các mức độ trong thủ tục đánh giá, xét ảnh hưởng tới tính toàn vẹn hữu cơ.","Lập bảng đầu vào và đầu ra theo SOP mục 3.2, dùng năng suất ước tính được duyệt.","Đọc lại SOP mục 4.2: chuyên gia đánh giá không nhận quà; mọi đề nghị ưu ái phải được ghi nhận và báo cáo."],en:["Put finding F-03 next to the grading definitions in the audit procedure and weigh its effect on organic integrity.","Build the input and output table in SOP 3.2 using the approved yield estimate.","Re-read SOP 4.2: auditors accept no gifts; any offer of favor must be recorded and reported."]}},learning:{summary:{vi:"Chuyên viên chứng nhận nông sản hữu cơ và truy xuất nguồn gốc đánh giá trang trại, cơ sở sơ chế theo tiêu chuẩn hữu cơ, VietGAP, GLOBALG.A.P.: kiểm tra hồ sơ, vật tư đầu vào, vùng đệm, lấy mẫu dư lượng, đối chiếu cân bằng khối lượng và hệ thống truy xuất. Nghề đòi hỏi kiến thức nông học, an toàn thực phẩm, kỹ năng đánh giá theo ISO 19011 và tính khách quan tuyệt đối theo ISO/IEC 17065.",en:"An organic and GAP certification auditor assesses farms and packhouses against organic, VietGAP and GLOBALG.A.P. standards: reviewing records, inputs and buffer zones, sampling for residues, reconciling mass balance and testing traceability. The role needs agronomy and food safety knowledge, ISO 19011 audit skills and absolute impartiality under ISO/IEC 17065."},responsibilities:{vi:["Lập kế hoạch đánh giá, xem xét hồ sơ đăng ký, bản đồ lô và kế hoạch sản xuất của khách hàng.","Đánh giá hiện trường: vật tư đầu vào, vùng đệm, kho, sơ chế, ghi chép và phỏng vấn người lao động.","Lấy mẫu đất, nước, sản phẩm để kiểm nghiệm dư lượng khi có nghi ngờ hoặc theo kế hoạch.","Đối chiếu cân bằng khối lượng và thử truy xuất xuôi, ngược một lô hàng.","Viết báo cáo, phân loại điểm không phù hợp, theo dõi khắc phục và đề xuất quyết định chứng nhận."],en:["Plan audits and review applications, plot maps and production plans.","Audit on site: inputs, buffer zones, stores, packing, records and worker interviews.","Sample soil, water and produce for residue testing when risk or the plan requires.","Reconcile mass balance and run forward and backward traceability tests on a lot.","Write reports, grade nonconformities, follow up corrections and recommend certification decisions."]},competencies:[{name:{vi:"Kỹ thuật đánh giá",en:"Audit technique"},desc:{vi:"Thu thập bằng chứng khách quan qua quan sát, phỏng vấn, hồ sơ và kết luận có căn cứ.",en:"Gather objective evidence by observation, interview and records and draw supported conclusions."}},{name:{vi:"Am hiểu tiêu chuẩn hữu cơ & GAP",en:"Organic & GAP standards"},desc:{vi:"Nắm danh mục vật tư được phép, thời gian chuyển đổi, vùng đệm và điểm kiểm soát GAP.",en:"Know permitted inputs, conversion periods, buffer zones and GAP control points."}},{name:{vi:"Truy xuất & cân bằng khối lượng",en:"Traceability & mass balance"},desc:{vi:"Đối chiếu năng suất, hóa đơn, tồn kho để phát hiện trộn lẫn hoặc bán vượt sản lượng.",en:"Match yields, invoices and stock to detect mixing or overselling."}},{name:{vi:"Đánh giá rủi ro & lấy mẫu",en:"Risk assessment & sampling"},desc:{vi:"Xác định điểm rủi ro ô nhiễm, chọn mẫu đại diện và đọc kết quả kiểm nghiệm dư lượng.",en:"Identify contamination risks, take representative samples and interpret residue results."}},{name:{vi:"Khách quan & liêm chính",en:"Impartiality & integrity"},desc:{vi:"Từ chối quà, khai báo xung đột lợi ích và giữ kết luận đúng bằng chứng.",en:"Refuse gifts, declare conflicts of interest and keep conclusions true to the evidence."}}],knowledge:{vi:["ISO/IEC 17065:2012 về yêu cầu đối với tổ chức chứng nhận sản phẩm, quá trình, dịch vụ và ISO 19011:2018 hướng dẫn đánh giá.","Nghị định 109/2018/NĐ-CP về nông nghiệp hữu cơ và bộ tiêu chuẩn TCVN 11041 về nông nghiệp hữu cơ.","TCVN 11892-1:2017 VietGAP trồng trọt và GLOBALG.A.P. IFA với các điểm kiểm soát Major Must, Minor Must.","Quy định hữu cơ của EU (Regulation (EU) 2018/848) và USDA NOP (7 CFR Part 205) cho thị trường xuất khẩu.","Nguyên tắc truy xuất nguồn gốc một bước trước, một bước sau và cân bằng khối lượng."],en:["ISO/IEC 17065:2012 requirements for bodies certifying products, processes and services, and ISO 19011:2018 audit guidelines.","Decree 109/2018/ND-CP on organic agriculture and the TCVN 11041 organic agriculture standards.","TCVN 11892-1:2017 VietGAP crop production and GLOBALG.A.P. IFA with Major Must and Minor Must control points.","EU organic rules (Regulation (EU) 2018/848) and USDA NOP (7 CFR Part 205) for export markets.","One-step-back, one-step-forward traceability and mass balance principles."]},tools:["Danh mục kiểm tra đánh giá (checklist)","Ứng dụng đánh giá trên máy tính bảng","Bộ lấy mẫu đất, nước và sản phẩm","Bảng tính cân bằng khối lượng","Hệ thống truy xuất nguồn gốc mã QR","Bản đồ GIS lô sản xuất"],kpis:{vi:["Tỷ lệ báo cáo đánh giá hoàn thành đúng hạn, đủ bằng chứng khách quan.","Tỷ lệ quyết định chứng nhận bị khiếu nại hoặc đảo ngược (càng thấp càng tốt).","Tỷ lệ điểm không phù hợp được khắc phục đúng hạn.","Số vi phạm về tính khách quan, xung đột lợi ích (mục tiêu bằng 0)."],en:["Share of audit reports completed on time with full objective evidence.","Share of certification decisions appealed or overturned (lower is better).","Share of nonconformities closed on time.","Impartiality or conflict-of-interest breaches (target zero)."]},day:[{time:"07:00",vi:"Họp khai mạc với trang trại, xác nhận phạm vi, lô sản xuất và kế hoạch đánh giá.",en:"Hold the opening meeting and confirm scope, plots and the audit plan."},{time:"08:30",vi:"Khảo sát lô trồng, vùng đệm, nguồn nước và kiểm tra kho vật tư đầu vào.",en:"Walk the plots, buffer zones and water sources and inspect the input store."},{time:"11:00",vi:"Phỏng vấn người lao động, kiểm tra nhật ký bón phân, phun thuốc và thu hoạch.",en:"Interview workers and check fertilizer, spray and harvest records."},{time:"14:00",vi:"Đối chiếu hóa đơn bán hàng, tồn kho với năng suất để lập cân bằng khối lượng.",en:"Match sales invoices and stock with yields to build the mass balance."},{time:"16:30",vi:"Họp kết thúc, thông báo điểm không phù hợp và thời hạn khắc phục.",en:"Hold the closing meeting and present nonconformities and deadlines."}],mistakes:{vi:["Hạ mức điểm không phù hợp nghiêm trọng thành nhẹ vì nể khách hàng.","Chấp nhận sản lượng nông hộ tự khai thay vì đối chiếu năng suất ước tính được duyệt.","Nhận quà, tiếp đãi vượt quy định, làm mất tính khách quan của cuộc đánh giá."],en:["Downgrading a serious nonconformity to minor to please the client.","Accepting the farmer's declared harvest instead of the approved yield estimate.","Accepting gifts or excessive hospitality, destroying audit impartiality."]},career:[{vi:"Chuyên gia đánh giá tập sự",en:"Trainee auditor"},{vi:"Chuyên gia đánh giá chứng nhận",en:"Certification auditor"},{vi:"Chuyên gia đánh giá trưởng",en:"Lead auditor"},{vi:"Trưởng phòng, Giám đốc Chứng nhận",en:"Certification Manager, Director"}],glossary:[{term:"Major NC",vi:"Điểm không phù hợp nặng: vi phạm ảnh hưởng trực tiếp đến tính toàn vẹn sản phẩm hoặc hệ thống, có thể dẫn tới đình chỉ chứng nhận.",en:"Major nonconformity: a breach directly affecting product or system integrity that may lead to suspension."},{term:"Mass balance",vi:"Cân bằng khối lượng: đối chiếu đầu vào, đầu ra, tồn kho để phát hiện bán vượt khả năng sản xuất.",en:"Reconciling inputs, outputs and stock to detect sales beyond production capacity."},{term:"Buffer zone",vi:"Vùng đệm: dải ngăn cách giữa lô hữu cơ và nguồn ô nhiễm hoặc khu canh tác thông thường.",en:"A strip separating organic plots from contamination sources or conventional farming."},{term:"Conversion period",vi:"Thời gian chuyển đổi: giai đoạn canh tác theo tiêu chuẩn hữu cơ trước khi sản phẩm được công nhận hữu cơ.",en:"The period of farming to organic rules before produce can be sold as organic."},{term:"Impartiality",vi:"Tính khách quan: quyết định chứng nhận dựa trên bằng chứng, không bị chi phối bởi lợi ích tài chính hay quan hệ.",en:"Certification decisions based on evidence, free from financial or personal influence."}],quiz:[{q:{vi:"Diện tích 3 ha, năng suất duyệt 20 tấn/ha, tồn đầu 1 tấn; bán hữu cơ 64 tấn, tồn cuối 2 tấn. Chênh lệch cân bằng khối lượng là bao nhiêu?",en:"Area 3 ha, approved yield 20 t/ha, opening stock 1 t; organic sales 64 t, closing stock 2 t. What is the mass balance excess?"},options:{vi:["0 tấn","3 tấn","5 tấn","7 tấn"],en:["0 t","3 t","5 t","7 t"]},answer:2,explain:{vi:"Đầu ra 64 + 2 = 66 tấn; đầu vào 1 + 3 x 20 = 61 tấn; chênh lệch 5 tấn cần điều tra.",en:"Output 64 + 2 = 66 t; input 1 + 3 x 20 = 61 t; the 5 t excess must be investigated."}},{q:{vi:"Khách hàng đưa phong bì và đề nghị ghi lỗi nhẹ. Bạn làm gì?",en:"A client offers an envelope and asks for a minor finding. What do you do?"},options:{vi:["Nhận vì là phong tục","Nhận nhưng vẫn ghi đúng lỗi","Đồng ý hạ lỗi một lần","Từ chối, ghi nhận sự việc, báo cấp quản lý và giữ đúng kết luận"],en:["Accept it as a custom","Accept it but grade correctly","Downgrade just this once","Refuse, record it, inform management and keep the conclusion"]},answer:3,explain:{vi:"ISO/IEC 17065 yêu cầu bảo đảm tính khách quan; nhận quà dù vẫn ghi đúng cũng tạo xung đột lợi ích.",en:"ISO/IEC 17065 requires impartiality; accepting a gift creates a conflict of interest even if grading stays correct."}},{q:{vi:"Tiêu chuẩn nào quy định yêu cầu đối với tổ chức chứng nhận sản phẩm?",en:"Which standard sets requirements for product certification bodies?"},options:{vi:["ISO/IEC 17065","ISO 9001","ISO 14001","ISO/IEC 17025"],en:["ISO/IEC 17065","ISO 9001","ISO 14001","ISO/IEC 17025"]},answer:0,explain:{vi:"ISO/IEC 17065 dành cho tổ chức chứng nhận sản phẩm; ISO/IEC 17025 dành cho phòng thử nghiệm.",en:"ISO/IEC 17065 covers product certification bodies; ISO/IEC 17025 covers testing laboratories."}},{q:{vi:"Trong GLOBALG.A.P. IFA, các điểm kiểm soát Major Must phải đạt mức tuân thủ bao nhiêu?",en:"In GLOBALG.A.P. IFA, what compliance level is required for Major Must control points?"},options:{vi:["95%","100%","80%","Không bắt buộc"],en:["95%","100%","80%","Not mandatory"]},answer:1,explain:{vi:"Major Must yêu cầu tuân thủ 100%; Minor Must yêu cầu từ 95% số điểm áp dụng.",en:"Major Musts require 100% compliance; Minor Musts require at least 95% of applicable points."}}],tools_en:["Audit checklist","Tablet-based audit app","Soil, water and product sampling kit","Mass balance spreadsheet","QR code traceability system","GIS maps of production plots"]}},"KK-941":{scenario:{company:"Công ty Tư vấn Môi trường Hưng Thịnh",supervisor:{name:"Cao Đức Mạnh",role:{vi:"Chủ nhiệm lập báo cáo ĐTM",en:"EIA Report Project Director"}},ref_code:"DTM-0526",title:{vi:"Đúng đối tượng nhạy cảm. Đúng mô hình lan truyền. Đánh giá trung thực.",en:"Right receptor. Right propagation model. Honest assessment."},brief:{vi:"Bạn hoàn thiện chương dự báo tiếng ồn của báo cáo đánh giá tác động môi trường DTM-0526 cho dự án cầu đường đô thị. Máy đóng cọc (nguồn điểm) đo 101 dBA ở 10 m; Trường Tiểu học Bình Minh cách vị trí đóng cọc 160 m. Đối chiếu bản nháp với hồ sơ đã duyệt, sửa phân loại khu vực của trường học và mức ồn dự báo tại trường (dBA, 1 chữ số thập phân), rồi lập báo cáo có căn cứ. Đây là tình huống đào tạo.",en:"You are finalizing the noise chapter of environmental impact assessment report DTM-0526 for an urban bridge and road project. The piling rig (a point source) measures 101 dBA at 10 m; Binh Minh Primary School is 160 m from the piling location. Compare the draft with the approved file, correct the school's zone class and the predicted noise level at the school (dBA, 1 decimal), then write an evidence-based report. This is a training scenario."},reference_title:{vi:"Hồ sơ khảo sát & dự báo tiếng ồn đã duyệt · DTM-0526",en:"Approved noise survey & prediction file · DTM-0526"},fields:[{id:"ZONE_CLASS",label:{vi:"Phân loại khu vực tại trường học",en:"Zone class at the school"},initial:"ZONE-NORMAL",expected:"ZONE-SPECIAL",choices:["ZONE-SPECIAL","ZONE-NORMAL","ZONE-INDUSTRIAL"],reference:"Phiếu khảo sát đối tượng nhạy cảm",hint:{vi:"Trường học, bệnh viện, thư viện, nhà trẻ là khu vực đặc biệt, cần bảo vệ nghiêm ngặt hơn khu dân cư thông thường.",en:"Schools, hospitals, libraries and nurseries are special zones needing stricter protection than ordinary residential areas."}},{id:"NOISE_DBA",label:{vi:"Mức ồn dự báo tại trường (dBA)",en:"Predicted noise at the school (dBA)"},initial:"89.0",expected:"76.9",reference:"Bảng tính lan truyền tiếng ồn",ref_value:{vi:"Nguồn điểm 101 dBA tại r1 = 10 m; trường học tại r2 = 160 m",en:"Point source 101 dBA at r1 = 10 m; school at r2 = 160 m"},hint:{vi:"Nguồn điểm suy giảm 6 dB mỗi lần gấp đôi khoảng cách; chỉ nguồn đường mới suy giảm 3 dB.",en:"A point source drops 6 dB per doubling of distance; only a line source drops 3 dB."}}],sop32:{vi:"Nguồn điểm, bỏ qua hấp thụ không khí và vật cản (mô phỏng): L2 = L1 - 20 x log10(r2 / r1); giới hạn mô phỏng ban ngày: khu vực đặc biệt 55 dBA, khu vực thông thường 70 dBA; làm tròn 1 chữ số thập phân.",en:"Point source, ignoring air absorption and barriers (training): L2 = L1 - 20 x log10(r2 / r1); training daytime limits: special zone 55 dBA, normal zone 70 dBA; round to 1 decimal place."},context:{label:"BÁO CÁO ĐTM / DTM-0526",metrics:[{label:{vi:"Mức ồn nguồn tại 10 m",en:"Source level at 10 m"},value:"101 dBA"},{label:{vi:"Khoảng cách tới trường",en:"Distance to school"},value:"160 m"},{label:{vi:"Giới hạn khu đặc biệt",en:"Special zone limit"},value:"55 dBA"}]},crisis:{vi:"Chủ đầu tư nhắn: “Bỏ trường học ra khỏi danh sách đối tượng nhạy cảm, ghi khu dân cư thông thường cho nhẹ. Hội đồng thẩm định họp tuần sau, không kịp làm biện pháp giảm ồn đâu.”",en:"The project owner texts: “Take the school off the sensitive receptor list and call it an ordinary residential area. The appraisal council meets next week and there is no time for noise mitigation.”"},options:{safe:{vi:"Giữ đúng phân loại khu vực đặc biệt và kết quả dự báo, báo Chủ nhiệm báo cáo; đề xuất tường chắn ồn, cọc khoan nhồi thay đóng cọc và không thi công trong giờ học.",en:"Keep the special zone class and the prediction, inform the EIA Project Director and propose noise barriers, bored piles instead of driven piles and no piling during school hours."},shortcut:{vi:"Đổi trường học thành khu dân cư thông thường để báo cáo trông đạt chuẩn và kịp hội đồng.",en:"Relabel the school as an ordinary residential area so the report looks compliant in time."},wait:{vi:"Gửi bản nháp như hiện tại và chờ hội đồng thẩm định tự phát hiện.",en:"Submit the draft as is and wait for the appraisal council to spot the problem."}},questions:{vi:["Vì sao trường học phải xếp ZONE-SPECIAL? Mức ồn dự báo vượt giới hạn mô phỏng bao nhiêu dB?","Trình bày cách tính lan truyền tiếng ồn từ nguồn điểm và trách nhiệm của đơn vị tư vấn nếu che giấu đối tượng nhạy cảm."],en:["Why must the school be classed ZONE-SPECIAL? By how many dB does the prediction exceed the training limit?","Explain your point-source propagation calculation and the consultant's liability for hiding a sensitive receptor."]},hints:{vi:["Rà danh sách đối tượng nhạy cảm trong bán kính ảnh hưởng và đối chiếu chức năng sử dụng của từng công trình.","Xác định loại nguồn trước, rồi áp đúng hệ số 20 log theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không được bỏ đối tượng nhạy cảm hay sửa kết quả dự báo; phải đề xuất biện pháp giảm thiểu khả thi."],en:["Review the sensitive receptors within the impact radius and check each building's actual use.","Identify the source type first, then apply the 20 log factor in SOP 3.2.","Re-read SOP 4.2: never drop a receptor or alter a prediction; propose feasible mitigation instead."]}},learning:{summary:{vi:"Chuyên viên đánh giá tác động môi trường nhận dạng, dự báo và đánh giá tác động của dự án đầu tư tới không khí, nước, đất, tiếng ồn, hệ sinh thái và cộng đồng; đề xuất biện pháp giảm thiểu, chương trình giám sát và tổ chức tham vấn. Nghề đòi hỏi kiến thức đa ngành, kỹ năng mô hình hóa, am hiểu Luật Bảo vệ môi trường và sự trung thực khoa học trước áp lực của chủ đầu tư.",en:"An environmental impact assessment specialist identifies, predicts and evaluates a project's effects on air, water, soil, noise, ecosystems and communities, and proposes mitigation, monitoring programs and public consultation. The role needs multidisciplinary knowledge, modeling skills, command of the Environmental Protection Law and scientific honesty under pressure from developers."},responsibilities:{vi:["Sàng lọc, xác định phân nhóm dự án và thủ tục môi trường phải thực hiện theo quy định.","Khảo sát, lấy mẫu hiện trạng môi trường nền và lập danh sách đối tượng nhạy cảm.","Dự báo tác động bằng mô hình lan truyền khí, ồn, nước và đánh giá mức độ tác động.","Đề xuất biện pháp giảm thiểu, chương trình quản lý và giám sát môi trường.","Tổ chức tham vấn cộng đồng, hoàn thiện báo cáo và giải trình trước hội đồng thẩm định."],en:["Screen projects and determine their category and the required environmental procedure.","Survey and sample baseline conditions and list sensitive receptors.","Predict impacts with air, noise and water models and rate their significance.","Propose mitigation measures and environmental management and monitoring programs.","Run public consultation, finalize the report and defend it before the appraisal council."]},competencies:[{name:{vi:"Sàng lọc & xác định phạm vi",en:"Screening & scoping"},desc:{vi:"Xác định nhóm dự án, ranh giới không gian, thời gian và các tác động chính cần đánh giá.",en:"Determine the project category, spatial and time boundaries and the key impacts to assess."}},{name:{vi:"Khảo sát môi trường nền",en:"Baseline survey"},desc:{vi:"Thiết kế mạng lưới lấy mẫu đại diện và bảo đảm số liệu đo thực tế, truy xuất được.",en:"Design representative sampling and ensure measured data is real and traceable."}},{name:{vi:"Mô hình hóa & dự báo",en:"Modeling & prediction"},desc:{vi:"Chọn đúng mô hình lan truyền, giả định thận trọng và kiểm tra độ nhạy của kết quả.",en:"Choose the right propagation model, use conservative assumptions and test sensitivity."}},{name:{vi:"Tham vấn cộng đồng",en:"Public consultation"},desc:{vi:"Trình bày tác động dễ hiểu, ghi nhận đầy đủ ý kiến và giải trình bằng văn bản.",en:"Explain impacts clearly, record all feedback and respond in writing."}},{name:{vi:"Trung thực khoa học",en:"Scientific integrity"},desc:{vi:"Không bỏ sót tác động, không sửa số liệu theo ý chủ đầu tư và báo cáo áp lực lên cấp trên.",en:"Never omit impacts or bend data for the developer, and escalate any pressure."}}],knowledge:{vi:["Luật Bảo vệ môi trường số 72/2020/QH14: phân nhóm dự án I, II, III, IV, đánh giá tác động môi trường và giấy phép môi trường.","Nghị định 08/2022/NĐ-CP và Thông tư 02/2022/TT-BTNMT: tiêu chí, nội dung và mẫu báo cáo đánh giá tác động môi trường.","Quy chuẩn kỹ thuật quốc gia về tiếng ồn, độ rung, chất lượng không khí và nước mặt (phiên bản hiện hành).","Nguyên lý lan truyền: suy giảm tiếng ồn nguồn điểm, nguồn đường và mô hình phát tán khí dạng Gauss.","Bộ tiêu chuẩn hoạt động về môi trường và xã hội của IFC (Performance Standards) cho dự án vay vốn quốc tế."],en:["Law on Environmental Protection No. 72/2020/QH14: project categories I to IV, EIA and environmental permits.","Decree 08/2022/ND-CP and Circular 02/2022/TT-BTNMT: EIA criteria, content and report templates.","National technical regulations on noise, vibration, ambient air and surface water quality (current editions).","Propagation principles: point and line source noise attenuation and Gaussian air dispersion models.","IFC Performance Standards on environmental and social sustainability for internationally financed projects."]},tools:["Phần mềm GIS và bản đồ nền","Mô hình phát tán khí dạng Gauss","Phần mềm dự báo tiếng ồn giao thông, thi công","Máy đo ồn tích phân","Thiết bị lấy mẫu không khí, nước","Ma trận đánh giá tác động"],kpis:{vi:["Tỷ lệ báo cáo được hội đồng thẩm định thông qua mà không phải lập lại.","Độ sai lệch giữa dự báo và kết quả quan trắc khi dự án triển khai.","Tỷ lệ ý kiến tham vấn được tiếp thu, giải trình đầy đủ.","Số lần bị phát hiện thiếu đối tượng nhạy cảm hoặc số liệu không trung thực (mục tiêu bằng 0)."],en:["Share of reports approved by the appraisal council without resubmission.","Gap between predictions and monitoring results once the project runs.","Share of consultation comments addressed in full.","Cases of missing receptors or untruthful data found (target zero)."]},day:[{time:"08:00",vi:"Rà soát hồ sơ thiết kế cơ sở, quy mô, công nghệ và tiến độ thi công của dự án.",en:"Review the basic design, scale, technology and construction schedule."},{time:"09:30",vi:"Khảo sát hiện trường, đo ồn nền, lấy mẫu và lập bản đồ đối tượng nhạy cảm.",en:"Survey the site, measure background noise, take samples and map sensitive receptors."},{time:"13:30",vi:"Chạy mô hình dự báo ồn, bụi và lập ma trận đánh giá mức độ tác động.",en:"Run noise and dust models and build the impact significance matrix."},{time:"15:30",vi:"Họp tham vấn với chính quyền địa phương, nhà trường và người dân.",en:"Hold consultation with local authorities, the school and residents."},{time:"17:00",vi:"Viết chương biện pháp giảm thiểu và cập nhật nhật ký giả định mô hình.",en:"Draft the mitigation chapter and update the model assumptions log."}],mistakes:{vi:["Bỏ sót hoặc xếp sai đối tượng nhạy cảm như trường học, bệnh viện, nguồn nước sinh hoạt.","Dùng công thức suy giảm của nguồn đường cho nguồn điểm, làm dự báo sai lệch lớn.","Sao chép số liệu môi trường nền từ báo cáo khác thay vì khảo sát thực tế."],en:["Missing or misclassifying receptors such as schools, hospitals or drinking water sources.","Using line-source attenuation for a point source, badly skewing the prediction.","Copying baseline data from another report instead of surveying the site."]},career:[{vi:"Chuyên viên tư vấn môi trường",en:"Environmental consultant"},{vi:"Chuyên viên đánh giá tác động môi trường",en:"EIA specialist"},{vi:"Chủ nhiệm lập báo cáo ĐTM",en:"EIA project director"},{vi:"Giám đốc tư vấn môi trường & xã hội",en:"Environmental & social consulting director"}],glossary:[{term:"EIA",vi:"Đánh giá tác động môi trường: phân tích, dự báo tác động của dự án và đề xuất biện pháp giảm thiểu.",en:"Environmental impact assessment: analyzing and predicting a project's impacts and proposing mitigation."},{term:"Sensitive receptor",vi:"Đối tượng nhạy cảm: nơi có người hoặc hệ sinh thái dễ bị tác động như trường học, bệnh viện, khu bảo tồn.",en:"A place where people or ecosystems are easily affected, such as schools, hospitals or protected areas."},{term:"dBA",vi:"Mức áp suất âm có trọng số A, mô phỏng độ nhạy của tai người theo tần số.",en:"A-weighted sound pressure level reflecting the human ear's sensitivity to frequency."},{term:"Baseline",vi:"Hiện trạng môi trường nền: chất lượng môi trường trước khi dự án triển khai, dùng để so sánh tác động.",en:"Environmental conditions before the project, used as the reference for impacts."},{term:"Mitigation hierarchy",vi:"Thứ tự giảm thiểu: tránh, giảm thiểu, phục hồi rồi mới bù đắp phần tác động còn lại.",en:"Avoid, minimize, restore, and only then offset residual impacts."}],quiz:[{q:{vi:"Nguồn điểm 95 dBA tại 10 m. Bỏ qua hấp thụ không khí, mức ồn tại 40 m xấp xỉ bao nhiêu?",en:"A point source is 95 dBA at 10 m. Ignoring air absorption, what is the level at 40 m?"},options:{vi:["89 dBA","83 dBA","77 dBA","91 dBA"],en:["89 dBA","83 dBA","77 dBA","91 dBA"]},answer:1,explain:{vi:"L2 = 95 - 20 x log10(4) = 95 - 12 = 83 dBA; 89 dBA là kết quả sai khi dùng công thức nguồn đường.",en:"L2 = 95 - 20 x log10(4) = 95 - 12 = 83 dBA; 89 dBA wrongly uses the line-source formula."}},{q:{vi:"Đối tượng nào thường được xếp là khu vực đặc biệt khi đánh giá tiếng ồn?",en:"Which receptor is usually treated as a special zone in noise assessment?"},options:{vi:["Bãi đỗ xe","Kho hàng","Trường học, bệnh viện","Khu công nghiệp"],en:["Car park","Warehouse","School, hospital","Industrial park"]},answer:2,explain:{vi:"Trường học, bệnh viện, thư viện, nhà trẻ cần sự yên tĩnh nên áp dụng giới hạn ồn nghiêm ngặt hơn.",en:"Schools, hospitals, libraries and nurseries need quiet and face stricter noise limits."}},{q:{vi:"Chủ đầu tư đề nghị bỏ một bệnh viện khỏi danh sách đối tượng nhạy cảm cho kịp thẩm định. Bạn làm gì?",en:"The developer asks you to drop a hospital from the receptor list to meet the appraisal date. What do you do?"},options:{vi:["Giữ đúng đối tượng nhạy cảm, báo cấp trên và đề xuất biện pháp giảm thiểu khả thi","Bỏ đi vì chủ đầu tư chịu trách nhiệm","Ghi chú mờ trong phụ lục","Hoãn thẩm định vô thời hạn"],en:["Keep the receptor, escalate and propose feasible mitigation","Drop it since the developer is responsible","Bury a note in an annex","Postpone the appraisal indefinitely"]},answer:0,explain:{vi:"Đơn vị tư vấn chịu trách nhiệm về tính trung thực của số liệu; che giấu đối tượng nhạy cảm là vi phạm pháp luật và đạo đức nghề.",en:"The consultant is accountable for truthful data; hiding a receptor breaches the law and professional ethics."}},{q:{vi:"Theo thứ tự giảm thiểu tác động, biện pháp nào được ưu tiên đầu tiên?",en:"In the mitigation hierarchy, which step comes first?"},options:{vi:["Bù đắp","Phục hồi","Giảm thiểu","Tránh tác động"],en:["Offset","Restore","Minimize","Avoid"]},answer:3,explain:{vi:"Ưu tiên tránh tác động ngay từ thiết kế; bù đắp chỉ áp dụng cho tác động còn lại sau cùng.",en:"Avoidance at the design stage comes first; offsets apply only to the final residual impacts."}}],tools_en:["GIS software and base maps","Gaussian air dispersion model","Traffic & construction noise prediction software","Integrating sound level meter","Air and water sampling equipment","Impact assessment matrix"]}},"KK-942":{scenario:{company:"Công ty TNHH Linh kiện Điện tử Hòa An",supervisor:{name:"Đinh Thị Ngọc Lan",role:{vi:"Trưởng phòng An toàn - Môi trường",en:"Environment, Health & Safety Manager"}},ref_code:"WST-Q3-25",title:{vi:"Phân loại đúng chất thải. Tính đúng tỷ lệ tái chế. Chuyển giao hợp pháp.",en:"Right waste class. Right recycling rate. Lawful handover."},brief:{vi:"Bạn lập báo cáo chất thải quý III WST-Q3-25 của nhà máy. Giẻ lau, găng tay dính dầu khoáng và dung môi từ xưởng bảo trì đang được ghi là chất thải công nghiệp thông thường. Tổng chất thải rắn phát sinh 486 tấn: tái chế 213.6 tấn, ủ phân hữu cơ 48 tấn, đốt thu hồi năng lượng 72.9 tấn, chôn lấp 151.5 tấn. Đối chiếu bản nháp với hồ sơ đã duyệt, sửa nhóm phân loại và tỷ lệ tái chế (%, 1 chữ số thập phân), rồi lập báo cáo có căn cứ.",en:"You are preparing the plant's Q3 waste report WST-Q3-25. Rags and gloves contaminated with mineral oil and solvents from the maintenance shop are recorded as ordinary industrial waste. Total solid waste was 486 t: recycled 213.6 t, composted 48 t, incinerated with energy recovery 72.9 t, landfilled 151.5 t. Compare the draft with the approved file, correct the waste class and the recycling rate (%, 1 decimal), then write an evidence-based report."},reference_title:{vi:"Sổ phân định & bảng cân đối chất thải đã duyệt · WST-Q3-25",en:"Approved waste classification & balance file · WST-Q3-25"},fields:[{id:"WASTE_CLASS",label:{vi:"Nhóm phân loại giẻ lau, găng tay dính dầu",en:"Class of oily rags and gloves"},initial:"NON-HAZ-IND",expected:"HAZARDOUS",choices:["HAZARDOUS","NON-HAZ-IND","DOMESTIC"],reference:"Sổ phân định chất thải",hint:{vi:"Giẻ lau, vật liệu thấm hút nhiễm dầu và dung môi mang thành phần nguy hại nên phải quản lý như chất thải nguy hại.",en:"Rags and absorbents contaminated with oil and solvents carry hazardous components and must be managed as hazardous waste."}},{id:"RECYCLE_PCT",label:{vi:"Tỷ lệ tái chế quý III (%)",en:"Q3 recycling rate (%)"},initial:"68.8",expected:"53.8",reference:"Bảng cân đối chất thải quý III",ref_value:{vi:"Tổng 486 t; tái chế 213.6 t; ủ phân 48 t; đốt thu hồi năng lượng 72.9 t; chôn lấp 151.5 t",en:"Total 486 t; recycled 213.6 t; composted 48 t; energy recovery 72.9 t; landfill 151.5 t"},hint:{vi:"Theo thứ bậc quản lý chất thải, thu hồi năng lượng đứng sau tái chế và không được tính là tái chế.",en:"In the waste hierarchy energy recovery ranks below recycling and does not count as recycling."}}],sop32:{vi:"Tỷ lệ tái chế = (khối lượng tái chế + ủ phân hữu cơ) / tổng chất thải phát sinh x 100; đốt thu hồi năng lượng và chôn lấp không được tính; làm tròn 1 chữ số thập phân.",en:"Recycling rate = (recycled + composted) / total waste generated x 100; energy recovery and landfill are excluded; round to 1 decimal place."},context:{label:"BÁO CÁO CHẤT THẢI / WST-Q3-25",metrics:[{label:{vi:"Tổng chất thải rắn",en:"Total solid waste"},value:"486 t"},{label:{vi:"Đốt thu hồi năng lượng",en:"Energy recovery"},value:"72.9 t"},{label:{vi:"Chôn lấp",en:"Landfill"},value:"151.5 t"}]},crisis:{vi:"Trưởng phòng Mua hàng nhắn: “Có đơn vị thu gom rẻ hơn 40%, không có giấy phép xử lý chất thải nguy hại nhưng nhận cả giẻ dầu. Cứ trộn chung vào chất thải thường giao cho họ, khỏi làm chứng từ.”",en:"The Purchasing Manager texts: “A collector is 40% cheaper. They have no hazardous waste permit but will take the oily rags. Mix them into general waste for them and skip the manifest.”"},options:{safe:{vi:"Từ chối trộn và chuyển giao trái phép; lưu giữ riêng chất thải nguy hại, chỉ giao cho đơn vị có giấy phép kèm chứng từ chất thải nguy hại; báo Trưởng phòng An toàn - Môi trường.",en:"Refuse mixing and unlawful handover; store hazardous waste separately, hand it only to a permitted operator with a manifest, and inform the EHS Manager."},shortcut:{vi:"Trộn giẻ dầu vào chất thải thường và giao cho đơn vị giá rẻ để tiết kiệm chi phí.",en:"Mix the oily rags into general waste and give them to the cheap collector."},wait:{vi:"Để giẻ dầu tồn đọng trong kho, không trả lời và chờ hợp đồng mới.",en:"Leave the oily rags piling up in storage, ignore the message and wait for a new contract."}},questions:{vi:["Vì sao giẻ lau, găng tay dính dầu phải xếp HAZARDOUS? Căn cứ phân định nào trong hồ sơ chứng minh?","Trình bày cách tính tỷ lệ tái chế và trách nhiệm của chủ nguồn thải khi giao chất thải nguy hại cho đơn vị không có giấy phép."],en:["Why must the oily rags and gloves be classed HAZARDOUS? Which classification evidence supports it?","Explain how you calculated the recycling rate and the generator's liability when handing hazardous waste to an unpermitted operator."]},hints:{vi:["Đối chiếu thành phần và nguồn phát sinh của giẻ lau với tiêu chí phân định chất thải nguy hại trong sổ phân định.","Chỉ cộng tái chế và ủ phân ở tử số theo SOP mục 3.2; mẫu số là tổng chất thải phát sinh.","Đọc lại SOP mục 4.2: chất thải nguy hại chỉ được chuyển giao cho đơn vị có giấy phép, kèm chứng từ."],en:["Check the rags' composition and source against the hazardous waste criteria in the classification register.","Only recycling and composting go in the numerator in SOP 3.2; the denominator is total waste generated.","Re-read SOP 4.2: hazardous waste goes only to permitted operators, always with a manifest."]}},learning:{summary:{vi:"Chuyên viên quản lý chất thải và kinh tế tuần hoàn phân định, thu gom, lưu giữ, chuyển giao chất thải đúng quy định; thiết kế chương trình giảm thiểu, tái sử dụng, tái chế và thu hồi vật liệu; theo dõi số liệu, báo cáo và thực hiện trách nhiệm mở rộng của nhà sản xuất (EPR). Nghề đòi hỏi am hiểu pháp luật môi trường, quy trình sản xuất, chuỗi cung ứng tái chế và tư duy thiết kế vòng đời sản phẩm.",en:"A waste management and circular economy specialist classifies, collects, stores and hands over waste lawfully; designs reduction, reuse, recycling and material recovery programs; tracks data, reports and delivers extended producer responsibility (EPR). The role needs knowledge of environmental law, production processes, recycling supply chains and life-cycle thinking."},responsibilities:{vi:["Phân định, phân loại chất thải tại nguồn và quản lý khu lưu giữ chất thải nguy hại.","Lựa chọn, giám sát đơn vị thu gom, xử lý có giấy phép và quản lý chứng từ chất thải nguy hại.","Theo dõi cân đối khối lượng chất thải, tỷ lệ tái chế và lập báo cáo định kỳ.","Thiết kế chương trình giảm thiểu, tái sử dụng bao bì, cộng sinh công nghiệp và thu hồi vật liệu.","Thực hiện nghĩa vụ trách nhiệm mở rộng của nhà sản xuất (EPR) và đào tạo người lao động."],en:["Classify and segregate waste at source and manage the hazardous waste store.","Select and audit permitted collectors and treaters and manage hazardous waste manifests.","Track the waste mass balance and recycling rate and file periodic reports.","Design reduction, packaging reuse, industrial symbiosis and material recovery programs.","Deliver extended producer responsibility (EPR) duties and train employees."]},competencies:[{name:{vi:"Phân định & phân loại chất thải",en:"Waste classification"},desc:{vi:"Xác định đúng chất thải nguy hại, công nghiệp thông thường và sinh hoạt theo nguồn và thành phần.",en:"Correctly identify hazardous, non-hazardous industrial and domestic waste by source and composition."}},{name:{vi:"Tuân thủ pháp luật môi trường",en:"Environmental compliance"},desc:{vi:"Bảo đảm lưu giữ, chuyển giao, chứng từ và báo cáo đúng quy định, lưu hồ sơ đầy đủ.",en:"Ensure lawful storage, handover, manifests and reporting with complete records."}},{name:{vi:"Phân tích dòng vật chất",en:"Material flow analysis"},desc:{vi:"Lập cân đối khối lượng, tìm điểm phát sinh lớn và cơ hội thu hồi giá trị.",en:"Build mass balances, find major waste sources and value recovery opportunities."}},{name:{vi:"Thiết kế giải pháp tuần hoàn",en:"Circular solution design"},desc:{vi:"Đề xuất tái sử dụng, thiết kế lại bao bì, cộng sinh công nghiệp và đo lường hiệu quả tuần hoàn.",en:"Propose reuse, packaging redesign and industrial symbiosis and measure circularity."}},{name:{vi:"Quản lý nhà thầu & chuỗi cung ứng",en:"Contractor & supply chain control"},desc:{vi:"Thẩm tra giấy phép, đánh giá định kỳ đơn vị xử lý và từ chối phương án giá rẻ trái luật.",en:"Verify permits, audit treaters regularly and reject cheap unlawful options."}}],knowledge:{vi:["Luật Bảo vệ môi trường số 72/2020/QH14: quản lý chất thải, kinh tế tuần hoàn và trách nhiệm mở rộng của nhà sản xuất.","Nghị định 08/2022/NĐ-CP và Thông tư 02/2022/TT-BTNMT: danh mục, mã chất thải, yêu cầu lưu giữ và chứng từ chất thải nguy hại.","Thứ bậc quản lý chất thải: phòng ngừa, giảm thiểu, tái sử dụng, tái chế, thu hồi năng lượng, xử lý và chôn lấp.","Công ước Basel về kiểm soát vận chuyển qua biên giới chất thải nguy hại.","ISO 14001:2015 và bộ tiêu chuẩn ISO 59000 về kinh tế tuần hoàn (ISO 59004, ISO 59020)."],en:["Law on Environmental Protection No. 72/2020/QH14: waste management, circular economy and extended producer responsibility.","Decree 08/2022/ND-CP and Circular 02/2022/TT-BTNMT: waste lists and codes, storage rules and hazardous waste manifests.","The waste hierarchy: prevention, reduction, reuse, recycling, energy recovery, treatment and landfill.","The Basel Convention on the control of transboundary movements of hazardous wastes.","ISO 14001:2015 and the ISO 59000 circular economy series (ISO 59004, ISO 59020)."]},tools:["Sổ phân định và nhật ký chất thải","Cân điện tử khu lưu giữ chất thải","Phần mềm quản lý dữ liệu môi trường","Hệ thống chứng từ chất thải nguy hại","Công cụ phân tích dòng vật chất (MFA)","Microsoft Excel và Power BI"],kpis:{vi:["Tỷ lệ tái chế và thu hồi vật liệu trên tổng chất thải phát sinh.","Khối lượng chất thải chôn lấp trên mỗi đơn vị sản phẩm.","Tỷ lệ chất thải nguy hại giao đúng đơn vị có giấy phép, đủ chứng từ (mục tiêu 100%).","Chi phí xử lý chất thải ròng sau khi trừ doanh thu phế liệu."],en:["Recycling and material recovery rate against total waste generated.","Landfilled waste per unit of output.","Share of hazardous waste handed to permitted operators with full manifests (target 100%).","Net waste cost after scrap revenue."]},day:[{time:"07:30",vi:"Kiểm tra khu lưu giữ: nhãn, biển cảnh báo, khay chống tràn và thời gian lưu giữ.",en:"Inspect the waste store: labels, warning signs, spill trays and storage time."},{time:"09:00",vi:"Cân, ghi sổ chất thải từ các xưởng và xử lý trường hợp phân loại sai tại nguồn.",en:"Weigh and log waste from each workshop and correct segregation errors at source."},{time:"11:00",vi:"Làm việc với đơn vị thu gom, kiểm tra giấy phép, phương tiện và ký chứng từ chuyển giao.",en:"Meet the collector, check permits and vehicles and sign the handover manifest."},{time:"14:00",vi:"Phân tích dòng vật chất, tìm cơ hội tái sử dụng bao bì và bán phế liệu sạch.",en:"Analyze material flows to find packaging reuse and clean scrap sales."},{time:"16:30",vi:"Cập nhật số liệu, báo cáo quản lý và kế hoạch đào tạo phân loại.",en:"Update data, report to management and plan segregation training."}],mistakes:{vi:["Xếp giẻ lau, vật liệu thấm hút dính dầu vào chất thải công nghiệp thông thường.","Tính đốt thu hồi năng lượng vào tỷ lệ tái chế, làm đẹp số liệu báo cáo.","Chọn đơn vị thu gom giá rẻ không có giấy phép, khiến chủ nguồn thải chịu trách nhiệm pháp lý."],en:["Classing oily rags and absorbents as ordinary industrial waste.","Counting energy recovery as recycling to flatter the report.","Choosing a cheap unpermitted collector, leaving the generator legally liable."]},career:[{vi:"Nhân viên môi trường nhà máy",en:"Plant environmental officer"},{vi:"Chuyên viên quản lý chất thải",en:"Waste management specialist"},{vi:"Trưởng nhóm kinh tế tuần hoàn",en:"Circular economy team lead"},{vi:"Trưởng phòng An toàn - Môi trường",en:"EHS Manager"}],glossary:[{term:"Hazardous waste",vi:"Chất thải nguy hại: chất thải chứa yếu tố độc, dễ cháy, ăn mòn, lây nhiễm hoặc đặc tính nguy hại khác.",en:"Waste with toxic, flammable, corrosive, infectious or other hazardous properties."},{term:"Waste manifest",vi:"Chứng từ chất thải nguy hại: tài liệu theo dõi chất thải từ chủ nguồn thải tới cơ sở xử lý.",en:"The document tracking hazardous waste from the generator to the treatment facility."},{term:"EPR",vi:"Trách nhiệm mở rộng của nhà sản xuất: nghĩa vụ tái chế hoặc đóng góp tài chính cho sản phẩm, bao bì đã bán ra.",en:"Extended producer responsibility: the duty to recycle, or fund recycling of, products and packaging sold."},{term:"Industrial symbiosis",vi:"Cộng sinh công nghiệp: chất thải, phụ phẩm của doanh nghiệp này làm nguyên liệu cho doanh nghiệp khác.",en:"One company's waste or by-products become another company's raw materials."},{term:"Recycling rate",vi:"Tỷ lệ tái chế: phần chất thải được tái chế hoặc ủ phân trên tổng lượng chất thải phát sinh.",en:"The share of generated waste that is recycled or composted."}],quiz:[{q:{vi:"Phát sinh 200 tấn: tái chế 70, ủ phân 20, đốt thu hồi năng lượng 40, chôn lấp 70. Tỷ lệ tái chế là bao nhiêu?",en:"200 t generated: 70 recycled, 20 composted, 40 energy recovery, 70 landfilled. What is the recycling rate?"},options:{vi:["65%","35%","55%","45%"],en:["65%","35%","55%","45%"]},answer:3,explain:{vi:"(70 + 20) / 200 = 45%; cộng cả đốt thu hồi năng lượng ra 65% là sai định nghĩa.",en:"(70 + 20) / 200 = 45%; adding energy recovery to get 65% misuses the definition."}},{q:{vi:"Theo thứ bậc quản lý chất thải, ưu tiên cao nhất là gì?",en:"What has the highest priority in the waste hierarchy?"},options:{vi:["Phòng ngừa và giảm thiểu phát sinh","Tái chế","Thu hồi năng lượng","Chôn lấp hợp vệ sinh"],en:["Prevention and reduction","Recycling","Energy recovery","Sanitary landfill"]},answer:0,explain:{vi:"Chất thải không phát sinh là chất thải tốt nhất; tái chế, thu hồi năng lượng và chôn lấp xếp sau.",en:"Waste never created is best; recycling, energy recovery and landfill come later."}},{q:{vi:"Đơn vị thu gom giá rẻ không có giấy phép đề nghị nhận chất thải nguy hại mà không cần chứng từ. Bạn làm gì?",en:"A cheap unpermitted collector offers to take hazardous waste without a manifest. What do you do?"},options:{vi:["Đồng ý vì tiết kiệm chi phí","Đồng ý nếu họ cam kết bằng miệng","Từ chối, chỉ giao cho đơn vị có giấy phép kèm chứng từ và báo cấp trên","Trộn vào chất thải thường"],en:["Agree to save money","Agree if they promise verbally","Refuse, use only permitted operators with manifests and escalate","Mix it into general waste"]},answer:2,explain:{vi:"Chủ nguồn thải chịu trách nhiệm khi chuyển giao sai; chỉ đơn vị có giấy phép và có chứng từ mới hợp pháp.",en:"The generator is liable for unlawful handover; only permitted operators with manifests are lawful."}},{q:{vi:"Văn bản nào hướng dẫn danh mục, mã chất thải và mẫu chứng từ chất thải nguy hại?",en:"Which instrument sets the waste list, waste codes and hazardous waste manifest form?"},options:{vi:["Luật Đầu tư","Thông tư 02/2022/TT-BTNMT","Luật Đất đai","ISO 9001"],en:["Investment Law","Circular 02/2022/TT-BTNMT","Land Law","ISO 9001"]},answer:1,explain:{vi:"Thông tư 02/2022/TT-BTNMT hướng dẫn Luật Bảo vệ môi trường, gồm danh mục chất thải và chứng từ chất thải nguy hại.",en:"Circular 02/2022/TT-BTNMT implements the Environmental Protection Law, including the waste list and manifests."}}],tools_en:["Waste classification register and logbook","Electronic scale at waste storage area","Environmental data management software","Hazardous waste manifest system","Material flow analysis (MFA) tools","Microsoft Excel and Power BI"]}},"KK-943":{scenario:{company:"Công ty CP Tín chỉ Carbon Đồng Xanh",supervisor:{name:"Mai Tuấn Kiệt",role:{vi:"Giám đốc Phát triển dự án carbon",en:"Carbon Project Development Director"}},ref_code:"MR-SOL07",title:{vi:"Đúng hệ số lưới. Đúng lượng giảm phát thải. Tín chỉ toàn vẹn.",en:"Right grid factor. Right reductions. Credits with integrity."},brief:{vi:"Bạn lập báo cáo giám sát MR-SOL07 cho dự án điện mặt trời áp mái nối lưới ở một khu công nghiệp, đăng ký theo tiêu chuẩn tín chỉ tự nguyện (mô phỏng). Năm giám sát, điện năng phát lên lưới đo được 72500 MWh. Hệ số lưới mô phỏng: biên vận hành EF_OM 0.79, biên xây dựng EF_BM 0.62 tCO2/MWh. Đối chiếu bản nháp với hồ sơ đã duyệt, sửa loại hệ số phát thải áp dụng và lượng giảm phát thải (tCO2e, làm tròn xuống số nguyên), rồi lập báo cáo có căn cứ.",en:"You are preparing monitoring report MR-SOL07 for a grid-connected rooftop solar project in an industrial park, registered under a voluntary carbon standard (training). Metered net supply to the grid in the monitoring year was 72500 MWh. Training grid factors: operating margin EF_OM 0.79 and build margin EF_BM 0.62 tCO2/MWh. Compare the draft with the approved file, correct the emission factor type and the emission reductions (tCO2e, rounded down to a whole number), then write an evidence-based report."},reference_title:{vi:"Tài liệu thiết kế dự án & phương pháp luận đã đăng ký · MR-SOL07",en:"Registered project design document & methodology · MR-SOL07"},fields:[{id:"EF_TYPE",label:{vi:"Loại hệ số phát thải lưới áp dụng",en:"Grid emission factor type applied"},initial:"EF-OM",expected:"EF-CM",choices:["EF-OM","EF-BM","EF-CM"],reference:"Phương pháp luận đã đăng ký mục 5",hint:{vi:"Dự án năng lượng tái tạo nối lưới dùng hệ số biên kết hợp, gộp có trọng số biên vận hành và biên xây dựng.",en:"Grid-connected renewable projects use the combined margin, a weighted mix of operating and build margins."}},{id:"ER_TCO2E",label:{vi:"Lượng giảm phát thải năm giám sát (tCO2e)",en:"Emission reductions in the monitoring year (tCO2e)"},initial:"57275",expected:"54193",reference:"Bảng tính giảm phát thải",ref_value:{vi:"Điện phát lên lưới 72500 MWh; EF_OM 0.79; EF_BM 0.62 tCO2/MWh; phát thải dự án và rò rỉ bằng 0",en:"Net grid supply 72500 MWh; EF_OM 0.79; EF_BM 0.62 tCO2/MWh; project emissions and leakage zero"},hint:{vi:"Tính hệ số biên kết hợp với trọng số dành cho điện mặt trời trước, rồi nhân với điện năng và làm tròn xuống.",en:"Compute the combined margin with the solar weights first, then multiply by energy and round down."}}],sop32:{vi:"Điện mặt trời, điện gió: EF_CM = 0.75 x EF_OM + 0.25 x EF_BM; giảm phát thải = điện phát lên lưới x EF_CM - phát thải dự án - rò rỉ; làm tròn xuống tấn nguyên (nguyên tắc thận trọng).",en:"Solar and wind: EF_CM = 0.75 x EF_OM + 0.25 x EF_BM; emission reductions = net grid supply x EF_CM - project emissions - leakage; round down to whole tonnes (conservativeness)."},context:{label:"BÁO CÁO GIÁM SÁT / MR-SOL07",metrics:[{label:{vi:"Điện phát lên lưới",en:"Net grid supply"},value:"72,500 MWh"},{label:{vi:"EF_OM mô phỏng",en:"Training EF_OM"},value:"0.79 tCO2/MWh"},{label:{vi:"EF_BM mô phỏng",en:"Training EF_BM"},value:"0.62 tCO2/MWh"}]},crisis:{vi:"Giám đốc kinh doanh nhắn: “Gộp luôn sản lượng 4 tháng trước ngày bắt đầu giai đoạn tín dụng vào báo cáo cho đủ 60000 tín chỉ đã ký bán kỳ hạn. Đơn vị thẩm tra không soát từng tháng đâu.”",en:"The Commercial Director texts: “Add the 4 months of output before the crediting period start date so we reach the 60000 credits sold forward. The verifier will not check month by month.”"},options:{safe:{vi:"Từ chối đưa sản lượng ngoài giai đoạn tín dụng; chỉ báo cáo dữ liệu đo trong kỳ, minh bạch với đơn vị thẩm tra; báo Giám đốc Phát triển dự án và đề xuất đàm phán lại khối lượng với người mua.",en:"Refuse to add output outside the crediting period; report only in-period metered data, stay transparent with the verifier, inform the Project Director and propose renegotiating volumes with the buyer."},shortcut:{vi:"Gộp sản lượng 4 tháng trước giai đoạn tín dụng để đủ khối lượng đã ký bán.",en:"Add the 4 pre-crediting months to reach the contracted volume."},wait:{vi:"Không phản hồi, nộp báo cáo nháp và để người mua tự xử lý phần thiếu hụt.",en:"Do not respond, submit the draft and leave the buyer to handle the shortfall."}},questions:{vi:["Vì sao báo cáo phải dùng EF-CM chứ không phải EF-OM? Trích căn cứ trong phương pháp luận đã đăng ký.","Trình bày cách tính lượng giảm phát thải và rủi ro toàn vẹn tín chỉ nếu đưa sản lượng ngoài giai đoạn tín dụng vào báo cáo."],en:["Why must the report use EF-CM rather than EF-OM? Cite the registered methodology.","Explain how you calculated the reductions and the credit integrity risk of including output outside the crediting period."]},hints:{vi:["Đọc mục hệ số phát thải của phương pháp luận đã đăng ký và đánh dấu loại hệ số đang dùng sai.","Tính EF_CM với trọng số cho điện mặt trời theo SOP mục 3.2 rồi mới nhân điện năng và làm tròn xuống.","Đọc lại SOP mục 4.2: chỉ được cấp tín chỉ cho giảm phát thải đo được trong giai đoạn tín dụng đã đăng ký."],en:["Read the emission factor section of the registered methodology and flag the wrong factor type.","Compute EF_CM with the solar weights in SOP 3.2, then multiply by energy and round down.","Re-read SOP 4.2: credits are issued only for reductions measured within the registered crediting period."]}},learning:{summary:{vi:"Chuyên viên phát triển dự án tín chỉ carbon xác định, thiết kế và đưa dự án giảm phát thải hoặc hấp thụ khí nhà kính qua toàn bộ chu trình: đánh giá khả thi, chọn phương pháp luận, chứng minh tính bổ sung, lập tài liệu thiết kế dự án, thẩm định, đăng ký, giám sát, thẩm tra và cấp tín chỉ. Nghề đòi hỏi kiến thức kỹ thuật, tài chính, pháp lý thị trường carbon và cam kết tuyệt đối với tính toàn vẹn môi trường.",en:"A carbon credit project developer identifies and designs emission reduction or removal projects and takes them through the full cycle: feasibility, methodology selection, additionality, project design document, validation, registration, monitoring, verification and issuance. The role needs technical, financial and carbon market legal knowledge and an absolute commitment to environmental integrity."},responsibilities:{vi:["Sàng lọc cơ hội dự án, đánh giá tiềm năng giảm phát thải và tính khả thi tài chính.","Chọn phương pháp luận, chứng minh tính bổ sung và lập tài liệu thiết kế dự án (PDD).","Làm việc với đơn vị thẩm định, thẩm tra (VVB) và cơ quan đăng ký tín chỉ.","Xây dựng kế hoạch giám sát, thu thập dữ liệu và lập báo cáo giám sát định kỳ.","Đàm phán hợp đồng mua bán tín chỉ, quản lý rủi ro giao hàng và chống tính trùng."],en:["Screen project opportunities and assess reduction potential and financial feasibility.","Select methodologies, demonstrate additionality and write the project design document (PDD).","Work with validation and verification bodies (VVBs) and the credit registry.","Build monitoring plans, collect data and prepare periodic monitoring reports.","Negotiate credit purchase agreements, manage delivery risk and prevent double counting."]},competencies:[{name:{vi:"Phương pháp luận & MRV",en:"Methodologies & MRV"},desc:{vi:"Áp dụng đúng công thức đường cơ sở, phát thải dự án, rò rỉ và kế hoạch đo đạc, báo cáo, thẩm tra.",en:"Apply baseline, project emission and leakage formulas and measurement, reporting and verification plans correctly."}},{name:{vi:"Tính bổ sung & đường cơ sở",en:"Additionality & baselines"},desc:{vi:"Phân tích rào cản, đầu tư và thực tiễn phổ biến để chứng minh dự án không phải kịch bản thông thường.",en:"Use barrier, investment and common practice analysis to show the project is not business as usual."}},{name:{vi:"Mô hình tài chính carbon",en:"Carbon finance modeling"},desc:{vi:"Dự báo dòng tín chỉ, chi phí chu trình và độ nhạy theo giá, sản lượng.",en:"Forecast credit flows, cycle costs and sensitivity to price and volume."}},{name:{vi:"Quan hệ thẩm định & đăng ký",en:"Validation & registry relations"},desc:{vi:"Chuẩn bị bằng chứng, trả lời phát hiện của VVB và theo dõi thủ tục cấp tín chỉ.",en:"Prepare evidence, answer VVB findings and track issuance procedures."}},{name:{vi:"Toàn vẹn tín chỉ",en:"Credit integrity"},desc:{vi:"Áp dụng nguyên tắc thận trọng, từ chối thổi phồng hay tính trùng và báo cáo áp lực sai lệch.",en:"Apply conservativeness, refuse inflation or double counting and escalate pressure to misstate."}}],knowledge:{vi:["Thỏa thuận Paris, Điều 6.2 và Điều 6.4, điều chỉnh tương ứng và yêu cầu chống tính trùng.","Công cụ tính hệ số phát thải lưới điện của CDM (Tool 07): biên vận hành, biên xây dựng và biên kết hợp.","ISO 14064-2:2019 về định lượng giảm phát thải cấp dự án và ISO 14064-3:2019 về thẩm định, thẩm tra.","Nguyên tắc Tín chỉ Carbon Cốt lõi (Core Carbon Principles) của ICVCM: bổ sung, lâu dài, định lượng chặt chẽ, không tính trùng.","Nghị định 06/2022/NĐ-CP và lộ trình phát triển thị trường carbon trong nước của Việt Nam."],en:["The Paris Agreement Articles 6.2 and 6.4, corresponding adjustments and double counting safeguards.","The CDM tool to calculate the emission factor for an electricity system (Tool 07): operating, build and combined margins.","ISO 14064-2:2019 on project-level GHG reduction quantification and ISO 14064-3:2019 on validation and verification.","The ICVCM Core Carbon Principles: additionality, permanence, robust quantification and no double counting.","Decree 06/2022/ND-CP and Vietnam's roadmap for a domestic carbon market."]},tools:["Bảng tính hệ số phát thải lưới","Mô hình tài chính dự án carbon","Phần mềm quản lý dữ liệu giám sát (MRV)","Hệ thống đăng ký tín chỉ (registry)","GIS và ảnh viễn thám","Đồng hồ đo đếm điện năng đã hiệu chuẩn"],kpis:{vi:["Tỷ lệ tín chỉ được cấp so với lượng dự kiến trong PDD.","Số yêu cầu khắc phục của đơn vị thẩm tra mỗi kỳ (càng ít càng tốt).","Thời gian từ khi kết thúc kỳ giám sát đến khi cấp tín chỉ.","Số sự cố tính trùng hoặc phải hủy tín chỉ (mục tiêu bằng 0)."],en:["Credits issued against the PDD estimate.","Corrective action requests from the verifier per period (fewer is better).","Time from the end of a monitoring period to issuance.","Double counting incidents or cancelled credits (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra dữ liệu đo đếm điện năng, nhật ký hiệu chuẩn đồng hồ và các khoảng trống dữ liệu.",en:"Check metered energy data, meter calibration logs and data gaps."},{time:"09:30",vi:"Cập nhật bảng tính giảm phát thải theo phương pháp luận đã đăng ký.",en:"Update the reduction calculations under the registered methodology."},{time:"13:30",vi:"Trả lời câu hỏi của đơn vị thẩm tra và bổ sung bằng chứng cho các phát hiện.",en:"Answer verifier queries and add evidence for open findings."},{time:"15:30",vi:"Họp với người mua về tiến độ giao tín chỉ và điều khoản hợp đồng.",en:"Meet the buyer about credit delivery schedules and contract terms."},{time:"17:00",vi:"Rà soát cơ hội dự án mới, đánh giá sơ bộ tính bổ sung và rủi ro.",en:"Screen new project opportunities for additionality and risk."}],mistakes:{vi:["Dùng biên vận hành thay cho biên kết hợp, làm thổi phồng lượng giảm phát thải.","Làm tròn lên hoặc chọn giả định lạc quan, vi phạm nguyên tắc thận trọng.","Bán cùng một lượng tín chỉ cho hai bên hoặc để chủ dự án vẫn tuyên bố trung hòa trên lượng đã bán, gây tính trùng."],en:["Using the operating margin instead of the combined margin, inflating reductions.","Rounding up or choosing optimistic assumptions, breaching conservativeness.","Selling the same credits twice or letting the host still claim neutrality on sold credits, causing double counting."]},career:[{vi:"Chuyên viên phân tích carbon",en:"Carbon analyst"},{vi:"Chuyên viên phát triển dự án carbon",en:"Carbon project developer"},{vi:"Quản lý danh mục dự án carbon",en:"Carbon portfolio manager"},{vi:"Giám đốc phát triển thị trường carbon",en:"Director of Carbon Markets"}],glossary:[{term:"Combined margin",vi:"Biên kết hợp: hệ số phát thải lưới gộp có trọng số giữa biên vận hành và biên xây dựng.",en:"A weighted average of the operating and build margin grid emission factors."},{term:"Additionality",vi:"Tính bổ sung: giảm phát thải chỉ xảy ra nhờ cơ chế tín chỉ, không phải hoạt động thông thường hay bắt buộc.",en:"Reductions happen only because of carbon finance, not business as usual or legal obligation."},{term:"Crediting period",vi:"Giai đoạn tín dụng: khoảng thời gian dự án được cấp tín chỉ cho giảm phát thải đã thẩm tra.",en:"The period during which verified reductions can earn credits."},{term:"VVB",vi:"Đơn vị thẩm định, thẩm tra độc lập được công nhận để đánh giá dự án và báo cáo giám sát.",en:"An accredited validation and verification body that assesses projects and monitoring reports."},{term:"Double counting",vi:"Tính trùng: cùng một lượng giảm phát thải được cấp, bán hoặc tuyên bố nhiều lần.",en:"The same reduction being issued, sold or claimed more than once."}],quiz:[{q:{vi:"Dự án điện gió có EF_OM 0.8 và EF_BM 0.6 tCO2/MWh, trọng số 0.75 và 0.25. Hệ số biên kết hợp EF_CM là bao nhiêu?",en:"A wind project has EF_OM 0.8 and EF_BM 0.6 tCO2/MWh with weights 0.75 and 0.25. What is EF_CM?"},options:{vi:["0.70","0.75","0.65","0.80"],en:["0.70","0.75","0.65","0.80"]},answer:1,explain:{vi:"Biên kết hợp: EF_CM = 0.75 x 0.8 + 0.25 x 0.6 = 0.6 + 0.15 = 0.75 tCO2/MWh.",en:"EF_CM = 0.75 x 0.8 + 0.25 x 0.6 = 0.6 + 0.15 = 0.75 tCO2/MWh."}},{q:{vi:"Nguyên tắc thận trọng yêu cầu gì khi dữ liệu có độ không chắc chắn?",en:"What does conservativeness require when data is uncertain?"},options:{vi:["Chọn giả định làm giảm lượng tín chỉ tính được","Chọn giả định có lợi nhất","Bỏ qua dữ liệu thiếu","Làm tròn lên"],en:["Choose assumptions that lower the credits claimed","Choose the most favorable assumptions","Ignore missing data","Round up"]},answer:0,explain:{vi:"Thận trọng nghĩa là không đánh giá quá cao giảm phát thải; khi nghi ngờ, chọn phương án cho ít tín chỉ hơn.",en:"Conservativeness means never overstating reductions; when in doubt, choose the option yielding fewer credits."}},{q:{vi:"Người mua muốn chủ dự án vẫn tuyên bố trung hòa carbon trên lượng tín chỉ đã bán cho họ. Bạn làm gì?",en:"The buyer is happy for the host to keep claiming carbon neutrality on credits sold to the buyer. What do you do?"},options:{vi:["Đồng ý vì cả hai cùng có lợi","Đồng ý nếu không công bố ra ngoài","Im lặng để hai bên tự thỏa thuận","Từ chối vì đó là tính trùng; ghi rõ quyền tuyên bố trong hợp đồng và báo cấp trên"],en:["Agree since both benefit","Agree if it stays private","Stay silent and let them agree","Refuse as double claiming; define claim rights in the contract and escalate"]},answer:3,explain:{vi:"Một tấn giảm phát thải chỉ được tuyên bố một lần; tuyên bố trùng làm mất tính toàn vẹn của tín chỉ.",en:"One tonne can be claimed only once; double claiming destroys credit integrity."}},{q:{vi:"Tiêu chuẩn nào hướng dẫn định lượng, giám sát và báo cáo giảm phát thải cấp dự án?",en:"Which standard guides project-level quantification, monitoring and reporting of GHG reductions?"},options:{vi:["ISO 14064-1","ISO 9001","ISO 14064-2","ISO 50001"],en:["ISO 14064-1","ISO 9001","ISO 14064-2","ISO 50001"]},answer:2,explain:{vi:"ISO 14064-2 dành cho cấp dự án; ISO 14064-1 dành cho kiểm kê cấp tổ chức.",en:"ISO 14064-2 covers projects; ISO 14064-1 covers organization-level inventories."}}],tools_en:["Grid emission factor spreadsheet","Carbon project financial model","Monitoring data management software (MRV)","Carbon credit registry","GIS and remote sensing imagery","Calibrated electricity meter"]}},"KK-944":{scenario:{company:"Thanh Lam Paper Mill JSC",supervisor:{name:"Đỗ Minh Khôi",role:{vi:"Trưởng đoàn kiểm toán năng lượng",en:"Lead Energy Auditor"}},ref_code:"EA-3105",title:{vi:"Đo thật. Tính đúng. Kiểm chứng được.",en:"Measure it. Calculate it. Verify it."},brief:{vi:"Bạn hoàn thiện báo cáo kiểm toán năng lượng EA-3105 cho giải pháp lắp biến tần (VSD) trên bơm nước làm mát 75 kW. Máy phân tích công suất ghi: trước cải tạo trung bình 62 kW, khi chạy thử biến tần 41 kW; bơm chạy 6000 giờ/năm, lưu lượng và giờ chạy đổi theo ca. Tiết kiệm dự kiến chỉ khoảng 3% điện năng toàn nhà máy. Sửa phương án đo lường và kiểm chứng (M&V) và mức tiết kiệm điện năm, rồi lập báo cáo có căn cứ.",en:"You are finalising energy audit report EA-3105 for a variable speed drive (VSD) on a 75 kW cooling water pump. The power analyser shows 62 kW average before the retrofit and 41 kW during the VSD trial; the pump runs 6000 hours per year and both flow and running hours vary by shift. Expected savings are only about 3% of plant electricity. Correct the measurement and verification (M&V) option and the annual savings, then write an evidence-based report."},reference_title:{vi:"Hồ sơ đo hiện trường & kế hoạch M&V đã duyệt · EA-3105",en:"Approved field measurement file & M&V plan · EA-3105"},fields:[{id:"MV_OPTION",label:{vi:"Phương án M&V theo IPMVP",en:"IPMVP M&V option"},initial:"IPMVP-A",expected:"IPMVP-B",choices:["IPMVP-A","IPMVP-B","IPMVP-C"],reference:"Kế hoạch đo lường & kiểm chứng (M&V)",hint:{vi:"Công suất và giờ chạy đều biến động thì phải đo mọi thông số trong ranh giới cách ly; tiết kiệm nhỏ so với toàn nhà máy thì không dùng đồng hồ tổng.",en:"When both power and hours vary, measure every parameter inside the retrofit boundary; small savings versus the whole plant rule out the main meter."}},{id:"SAVING_KWH",label:{vi:"Tiết kiệm điện năm (kWh)",en:"Annual electricity savings (kWh)"},initial:"204000",expected:"126000",reference:"Biên bản đo công suất trước và sau",ref_value:{vi:"Nhãn động cơ 75 kW; đo trung bình trước 62 kW, sau 41 kW; 6000 giờ/năm",en:"Motor nameplate 75 kW; measured average 62 kW before, 41 kW after; 6000 h/year"},hint:{vi:"Tính tiết kiệm từ công suất đo thực tế, không lấy công suất định mức ghi trên nhãn động cơ.",en:"Calculate savings from measured power, never from the rated power on the motor nameplate."}}],sop32:{vi:"Tiết kiệm điện năm (kWh) = (công suất đo trung bình trước cải tạo - công suất đo sau cải tạo) x số giờ vận hành năm; không dùng công suất định mức trên nhãn động cơ.",en:"Annual savings (kWh) = (measured average power before retrofit - measured power after retrofit) x annual operating hours; never use the motor nameplate rating."},context:{label:"BÁO CÁO NHÁP / EA-3105",metrics:[{label:{vi:"Công suất đo trước",en:"Measured power before"},value:"62 kW"},{label:{vi:"Công suất đo sau",en:"Measured power after"},value:"41 kW"},{label:{vi:"Giờ vận hành năm",en:"Annual operating hours"},value:"6000 h"}]},crisis:{vi:"Giám đốc nhà máy nhắn: “Cứ ghi 204000 kWh theo công suất nhãn đi, hồ sơ vay tín dụng xanh cần tiết kiệm trên 150000 kWh mới đạt. Ngân hàng chỉ xem tổng số, sáng mai phải nộp.”",en:"The plant director messages you: “Just write 204000 kWh using the nameplate power, the green loan file needs more than 150000 kWh of savings to qualify. The bank only looks at the total and it is due tomorrow morning.”"},options:{safe:{vi:"Giữ kết quả đo 126000 kWh, báo trưởng đoàn kiểm toán, đề xuất bổ sung giải pháp có căn cứ (động cơ hiệu suất cao, giảm áp hệ thống) để hồ sơ đạt ngưỡng một cách trung thực.",en:"Keep the measured 126000 kWh, inform the lead auditor and propose additional evidence-based measures (high-efficiency motor, lower system pressure) so the file can qualify honestly."},shortcut:{vi:"Ghi 204000 kWh theo công suất nhãn để kịp hồ sơ vay, sau này kiểm chứng lại sau.",en:"Write 204000 kWh from the nameplate to meet the loan deadline and verify later."},wait:{vi:"Tạm không nộp báo cáo và chờ giám đốc nhà máy tự quyết định số liệu.",en:"Hold the report and wait for the plant director to decide the figures."}},questions:{vi:["Vì sao chọn IPMVP-B thay vì IPMVP-A hay IPMVP-C? Dữ liệu đo nào chứng minh lựa chọn của bạn?","Trình bày cách tính 126000 kWh và rủi ro pháp lý, tài chính nếu khai tiết kiệm theo công suất nhãn động cơ."],en:["Why did you choose IPMVP-B instead of IPMVP-A or IPMVP-C? Which measurements support your choice?","Explain how you calculated 126000 kWh and the legal and financial risks of reporting savings from the motor nameplate."]},hints:{vi:["Đặt kế hoạch M&V cạnh biên bản đo và đánh dấu thông số nào đang biến động theo ca.","Lấy hiệu công suất đo trước và sau nhân với giờ vận hành theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi yêu cầu nâng số tiết kiệm phải báo trưởng đoàn, không được sửa số đo."],en:["Place the M&V plan next to the measurement record and flag which parameters vary by shift.","Multiply the measured power difference by operating hours as set out in SOP 3.2.","Re-read SOP 4.2: any request to inflate savings must go to the lead auditor; measured data is never altered."]}},learning:{summary:{vi:"Kiểm toán viên năng lượng khảo sát, đo đạc và phân tích cách nhà máy, tòa nhà sử dụng điện, nhiệt và nhiên liệu để tìm tổn thất, đề xuất giải pháp tiết kiệm có tính toán kinh tế kèm kế hoạch đo lường, kiểm chứng. Nghề đòi hỏi kỹ năng đo hiện trường, hiểu hệ thống động lực (bơm, quạt, máy nén, lò hơi, điều hòa, chiếu sáng), phân tích số liệu và giữ tính độc lập, trung thực trong báo cáo.",en:"An energy auditor surveys, measures and analyses how plants and buildings use electricity, heat and fuel to find losses, then proposes savings measures with economic analysis and a measurement and verification plan. The role requires field measurement skills, knowledge of utility systems (pumps, fans, compressors, boilers, HVAC, lighting), data analysis and strict independence and honesty in reporting."},responsibilities:{vi:["Thu thập hóa đơn năng lượng, sơ đồ hệ thống và lập đường cơ sở tiêu thụ năng lượng.","Đo đạc hiện trường: công suất, chất lượng điện, lưu lượng, nhiệt độ, khí thải lò hơi.","Phân tích tổn thất và đề xuất giải pháp tiết kiệm (ECM) kèm chi phí, tiết kiệm, thời gian hoàn vốn.","Xây dựng kế hoạch đo lường và kiểm chứng (M&V) cho từng giải pháp.","Lập báo cáo kiểm toán năng lượng, trình bày với ban lãnh đạo và theo dõi kết quả triển khai."],en:["Collect energy bills and system diagrams and build the energy consumption baseline.","Take field measurements: power, power quality, flow, temperature and boiler flue gas.","Analyse losses and propose energy conservation measures (ECMs) with cost, savings and payback.","Design a measurement and verification (M&V) plan for each measure.","Write the energy audit report, present it to management and follow up on implementation."]},competencies:[{name:{vi:"Đo đạc hiện trường",en:"Field measurement"},desc:{vi:"Lắp đặt an toàn thiết bị phân tích công suất, data logger, camera nhiệt và đọc đúng số liệu.",en:"Safely install power analysers, data loggers and thermal cameras and read the data correctly."}},{name:{vi:"Phân tích hệ thống động lực",en:"Utility system analysis"},desc:{vi:"Hiểu đặc tính bơm, quạt, khí nén, hơi, lạnh và định luật tương tự để ước tính tiềm năng tiết kiệm.",en:"Understand pump, fan, compressed air, steam and chiller behaviour and the affinity laws to estimate savings."}},{name:{vi:"Đánh giá kinh tế giải pháp",en:"Economic appraisal"},desc:{vi:"Tính thời gian hoàn vốn, NPV, IRR và xếp hạng giải pháp theo hiệu quả đầu tư.",en:"Calculate payback, NPV and IRR and rank measures by investment return."}},{name:{vi:"Đo lường & kiểm chứng",en:"Measurement & verification"},desc:{vi:"Chọn phương án IPMVP phù hợp, điều chỉnh đường cơ sở theo sản lượng, thời tiết.",en:"Select the right IPMVP option and adjust the baseline for production and weather."}},{name:{vi:"Độc lập & trung thực",en:"Independence & integrity"},desc:{vi:"Báo cáo đúng số đo dù khách hàng muốn kết quả đẹp hơn để vay vốn hay nhận ưu đãi.",en:"Report measured results even when the client wants better numbers for loans or incentives."}}],knowledge:{vi:["Luật Sử dụng năng lượng tiết kiệm và hiệu quả số 50/2010/QH12 và các văn bản sửa đổi, hướng dẫn về cơ sở sử dụng năng lượng trọng điểm và kiểm toán năng lượng định kỳ.","ISO 50001 về hệ thống quản lý năng lượng và ISO 50002 về yêu cầu đối với kiểm toán năng lượng.","Giao thức quốc tế đo lường và kiểm chứng hiệu quả (IPMVP) với 4 phương án A, B, C, D.","Định luật tương tự của bơm, quạt: lưu lượng tỷ lệ tốc độ, cột áp tỷ lệ bình phương, công suất tỷ lệ lập phương tốc độ.","Quy đổi năng lượng về tấn dầu tương đương (TOE), suất tiêu hao năng lượng và hệ số phát thải khí nhà kính."],en:["Law on Economical and Efficient Use of Energy No. 50/2010/QH12 and its amending and guiding documents on designated energy users and periodic energy audits.","ISO 50001 on energy management systems and ISO 50002 on energy audit requirements.","International Performance Measurement and Verification Protocol (IPMVP) with options A, B, C and D.","Pump and fan affinity laws: flow varies with speed, head with speed squared and power with speed cubed.","Conversion to tonnes of oil equivalent (TOE), specific energy consumption and greenhouse gas emission factors."]},tools:["Máy phân tích công suất & chất lượng điện","Camera nhiệt hồng ngoại","Máy phân tích khí thải lò hơi","Đồng hồ đo lưu lượng siêu âm","Bộ ghi dữ liệu (data logger)","Bảng tính phân tích kinh tế ECM"],kpis:{vi:["Độ lệch giữa tiết kiệm kiểm chứng và tiết kiệm dự báo (mục tiêu dưới 10%).","Tỷ lệ giải pháp đề xuất được doanh nghiệp triển khai.","Thời gian hoàn thành báo cáo sau khảo sát hiện trường.","Số sai sót số liệu phát hiện khi thẩm định báo cáo (mục tiêu bằng 0)."],en:["Gap between verified and predicted savings (target below 10%).","Share of proposed measures implemented by the client.","Report turnaround time after the site survey.","Data errors found during report review (target zero)."]},day:[{time:"07:30",vi:"Họp an toàn với nhà máy, nhận giấy phép làm việc khu vực trạm bơm và tủ điện.",en:"Safety briefing with the plant and work permit for the pump house and switchboards."},{time:"09:00",vi:"Lắp máy phân tích công suất và data logger trên tủ điện bơm, kiểm tra kẹp dòng.",en:"Install the power analyser and data logger on the pump panel and check the current clamps."},{time:"11:00",vi:"Đo khí thải lò hơi, quét camera nhiệt đường ống hơi tìm điểm mất nhiệt.",en:"Measure boiler flue gas and scan steam pipes with a thermal camera for heat losses."},{time:"14:00",vi:"Tải dữ liệu đo, lập đường cơ sở và tính tiết kiệm cho từng giải pháp.",en:"Download the logged data, build the baseline and calculate savings per measure."},{time:"16:30",vi:"Tính thời gian hoàn vốn, viết kế hoạch M&V và cập nhật báo cáo nháp.",en:"Calculate payback, write the M&V plan and update the draft report."}],mistakes:{vi:["Dùng công suất định mức trên nhãn thay cho công suất đo thực tế, làm thổi phồng tiết kiệm.","Cộng dồn tiết kiệm của các giải pháp tương tác nhau (biến tần và động cơ mới) như thể độc lập.","Chọn phương án M&V không phù hợp với mức biến động của phụ tải và quy mô tiết kiệm."],en:["Using nameplate power instead of measured power, which inflates savings.","Adding up savings from interacting measures (VSD and new motor) as if they were independent.","Choosing an M&V option that does not match load variability and the size of the savings."]},career:[{vi:"Kỹ thuật viên đo đạc năng lượng",en:"Energy measurement technician"},{vi:"Kiểm toán viên năng lượng",en:"Energy auditor"},{vi:"Trưởng đoàn kiểm toán năng lượng",en:"Lead energy auditor"},{vi:"Chuyên gia tư vấn quản lý năng lượng & ESG",en:"Energy management & ESG consultant"}],glossary:[{term:"ECM",vi:"Giải pháp tiết kiệm năng lượng (Energy Conservation Measure) được đề xuất trong báo cáo kiểm toán.",en:"Energy Conservation Measure proposed in an energy audit report."},{term:"IPMVP",vi:"Giao thức quốc tế đo lường và kiểm chứng hiệu quả, gồm 4 phương án A, B, C, D.",en:"International Performance Measurement and Verification Protocol with options A, B, C and D."},{term:"TOE",vi:"Tấn dầu tương đương, đơn vị quy đổi chung để so sánh các dạng năng lượng.",en:"Tonne of oil equivalent, a common unit for comparing energy forms."},{term:"Baseline",vi:"Đường cơ sở: mức tiêu thụ năng lượng trước cải tạo, dùng để so sánh và tính tiết kiệm.",en:"Energy use before the retrofit, used as the reference for calculating savings."},{term:"VSD",vi:"Biến tần điều chỉnh tốc độ động cơ theo nhu cầu thực tế thay cho tiết lưu bằng van.",en:"Variable speed drive that matches motor speed to demand instead of throttling with valves."}],quiz:[{q:{vi:"Bơm ly tâm giảm tốc độ còn 80% nhờ biến tần, công suất trục lý thuyết còn khoảng bao nhiêu?",en:"A centrifugal pump is slowed to 80% speed with a VSD. What is the theoretical shaft power?"},options:{vi:["80%","64%","51%","40%"],en:["80%","64%","51%","40%"]},answer:2,explain:{vi:"Theo định luật tương tự, công suất tỷ lệ lập phương tốc độ: 0.8 x 0.8 x 0.8 = 0.512, khoảng 51%.",en:"Under the affinity laws power varies with speed cubed: 0.8 x 0.8 x 0.8 = 0.512, about 51%."}},{q:{vi:"Phụ tải và giờ chạy đều biến động, tiết kiệm nhỏ so với toàn nhà máy. Nên chọn phương án IPMVP nào?",en:"Load and running hours both vary and savings are small versus the whole plant. Which IPMVP option fits?"},options:{vi:["Phương án A","Phương án B","Phương án C","Không cần M&V"],en:["Option A","Option B","Option C","No M&V needed"]},answer:1,explain:{vi:"Phương án B đo liên tục mọi thông số trong ranh giới cách ly, phù hợp khi phụ tải biến động; phương án C cần tiết kiệm đủ lớn so với đồng hồ tổng.",en:"Option B measures all parameters inside the boundary, suited to variable loads; Option C needs savings large enough to show on the main meter."}},{q:{vi:"Khách hàng đề nghị tăng số tiết kiệm trong báo cáo để đạt điều kiện vay vốn. Bạn làm gì?",en:"The client asks you to raise the savings in the report to qualify for a loan. What do you do?"},options:{vi:["Sửa số theo yêu cầu","Nộp báo cáo nhưng không ký","Bỏ trống mục tiết kiệm","Giữ số đo, báo trưởng đoàn và đề xuất giải pháp bổ sung hợp lệ"],en:["Change the figures as asked","Submit the report unsigned","Leave the savings section blank","Keep measured data, inform the lead auditor and propose valid extra measures"]},answer:3,explain:{vi:"Kiểm toán viên phải độc lập; thổi phồng tiết kiệm là gian lận với ngân hàng và gây rủi ro pháp lý cho cả hai bên.",en:"Auditors must stay independent; inflating savings misleads the bank and creates legal risk for both parties."}},{q:{vi:"Giải pháp đầu tư 480 triệu đồng, tiết kiệm 240 triệu đồng mỗi năm. Thời gian hoàn vốn giản đơn là bao lâu?",en:"A measure costs 480 million VND and saves 240 million VND per year. What is the simple payback?"},options:{vi:["2 năm","0.5 năm","4 năm","20 năm"],en:["2 years","0.5 years","4 years","20 years"]},answer:0,explain:{vi:"Thời gian hoàn vốn giản đơn = vốn đầu tư / tiết kiệm hằng năm = 480 / 240 = 2 năm.",en:"Simple payback = investment / annual savings = 480 / 240 = 2 years."}}],tools_en:["Power & power quality analyzer","Infrared thermal camera","Boiler flue gas analyzer","Ultrasonic flow meter","Data logger","ECM economic analysis spreadsheet"]}},"KK-945":{scenario:{company:"Ngoc Ha Environmental Lab",supervisor:{name:"Tạ Minh Nguyệt",role:{vi:"Trưởng phòng Quan trắc hiện trường",en:"Field Monitoring Manager"}},ref_code:"QT-2611",title:{vi:"Mẫu đúng cách. Số đúng thực. Báo cáo đúng luật.",en:"Right sample. True numbers. Lawful report."},brief:{vi:"Bạn hoàn thiện phiếu kết quả quan trắc QT-2611 cho nước thải sau xử lý của một nhà máy dệt nhuộm. Trong ca 8 giờ đã lấy 4 mẫu đơn: COD 118, 186, 154, 92 mg/L tại lưu lượng 40, 80, 60, 20 m3/h. Một chai riêng được lấy để phân tích chì (Pb) tổng. Rà soát phiếu nháp, sửa hóa chất bảo quản mẫu Pb và COD trung bình theo lưu lượng (giới hạn mô phỏng 150 mg/L), rồi lập báo cáo có căn cứ.",en:"You are finalising monitoring result sheet QT-2611 for treated effluent from a textile dyeing plant. Over an 8-hour shift, 4 grab samples were taken: COD 118, 186, 154 and 92 mg/L at flows of 40, 80, 60 and 20 m3/h. A separate bottle was collected for total lead (Pb). Review the draft, correct the Pb sample preservative and the flow-weighted COD (training limit 150 mg/L), then write an evidence-based report."},reference_title:{vi:"Nhật ký hiện trường & bảng bảo quản mẫu đã duyệt · QT-2611",en:"Approved field log & sample preservation table · QT-2611"},fields:[{id:"PB_PRESERV",label:{vi:"Bảo quản mẫu chì (Pb)",en:"Lead (Pb) sample preservation"},initial:"H2SO4 pH<2",expected:"HNO3 pH<2",choices:["H2SO4 pH<2","HNO3 pH<2","NaOH pH>12"],reference:"Bảng bảo quản mẫu theo ISO 5667-3",hint:{vi:"Mẫu kim loại được axit hóa bằng axit nitric; axit sunfuric tạo kết tủa chì sunfat, NaOH chỉ dùng cho mẫu xyanua.",en:"Metal samples are acidified with nitric acid; sulphuric acid precipitates lead sulphate and NaOH is only for cyanide samples."}},{id:"COD_FW",label:{vi:"COD trung bình theo lưu lượng (mg/L)",en:"Flow-weighted COD (mg/L)"},initial:"137.5",expected:"153.4",reference:"Nhật ký lưu lượng & kết quả COD",ref_value:{vi:"COD 118/186/154/92 mg/L tại lưu lượng 40/80/60/20 m3/h",en:"COD 118/186/154/92 mg/L at flows of 40/80/60/20 m3/h"},hint:{vi:"Mẫu lấy lúc lưu lượng lớn phải có trọng số lớn hơn; trung bình cộng che mất đỉnh ô nhiễm.",en:"Samples taken at high flow must carry more weight; a simple average hides the pollution peak."}}],sop32:{vi:"COD đại diện ca = tổng (Ci x Qi) / tổng Qi, lấy 1 chữ số thập phân; không dùng trung bình cộng khi lưu lượng tại các thời điểm lấy mẫu khác nhau.",en:"Shift COD = sum of (Ci x Qi) / sum of Qi, to 1 decimal place; never use a simple average when flows differ between sampling times."},context:{label:"PHIẾU KẾT QUẢ NHÁP / QT-2611",metrics:[{label:{vi:"Số mẫu đơn",en:"Grab samples"},value:"4"},{label:{vi:"Tổng lưu lượng các mẫu",en:"Sum of sample flows"},value:"200 m3/h"},{label:{vi:"Giới hạn COD mô phỏng",en:"Training COD limit"},value:"150 mg/L"}]},crisis:{vi:"Quản lý môi trường của nhà máy gọi: “Bỏ mẫu lúc 11 giờ đi, ghi trung bình cộng 137.5 cho đạt. Tuần sau đoàn kiểm tra xuống, hợp đồng quan trắc năm tới vẫn là của bên em.”",en:"The plant's environmental manager calls: “Drop the 11 o'clock sample and report the simple average of 137.5 so it passes. The inspectors come next week, and next year's monitoring contract stays with you.”"},options:{safe:{vi:"Báo cáo đúng 153.4 mg/L kèm toàn bộ dữ liệu, giữ mẫu lưu và nhật ký, báo trưởng phòng và bộ phận đảm bảo chất lượng; đề xuất nhà máy rà soát hệ thống xử lý và lấy mẫu lặp lại có giám sát.",en:"Report the correct 153.4 mg/L with all data, keep retained samples and logs, inform the manager and QA; advise the plant to review its treatment system and repeat sampling under supervision."},shortcut:{vi:"Loại mẫu lúc 11 giờ và ghi 137.5 mg/L để khách hàng hài lòng, giữ hợp đồng năm sau.",en:"Drop the 11 o'clock sample and report 137.5 mg/L to keep the client and next year's contract."},wait:{vi:"Chưa phát hành phiếu, chờ khách hàng tự quyết định giữ hay bỏ mẫu.",en:"Hold the sheet and wait for the client to decide whether to keep the sample."}},questions:{vi:["Vì sao COD đại diện là 153.4 mg/L chứ không phải 137.5 mg/L? Dữ liệu lưu lượng nào chứng minh?","Nếu mẫu Pb đã bị axit hóa sai bằng H2SO4, bạn xử lý mẫu và báo cáo thế nào để không mất giá trị pháp lý của kết quả?"],en:["Why is the representative COD 153.4 mg/L rather than 137.5 mg/L? Which flow data proves it?","If the Pb sample was wrongly acidified with H2SO4, how do you handle the sample and the report so the result keeps its legal value?"]},hints:{vi:["Đặt phiếu nháp cạnh bảng bảo quản mẫu và đánh dấu hóa chất dùng cho chai Pb.","Nhân từng nồng độ với lưu lượng tương ứng rồi chia tổng lưu lượng theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không được loại mẫu hợp lệ theo yêu cầu khách hàng; mọi áp lực phải báo cáo."],en:["Place the draft next to the preservation table and flag the preservative used for the Pb bottle.","Multiply each concentration by its flow and divide by total flow as set out in SOP 3.2.","Re-read SOP 4.2: valid samples are never dropped at the client's request; any pressure must be reported."]}},learning:{summary:{vi:"Kỹ thuật viên quan trắc môi trường lấy mẫu, đo nhanh tại hiện trường, bảo quản và vận chuyển mẫu nước, khí, đất theo phương pháp chuẩn để phòng thí nghiệm phân tích. Số liệu quan trắc là căn cứ để doanh nghiệp báo cáo cơ quan quản lý và để xã hội giám sát ô nhiễm, nên người làm nghề phải nắm vững kỹ thuật lấy mẫu, chuỗi hành trình mẫu, kiểm soát chất lượng và trung thực tuyệt đối.",en:"An environmental monitoring technician collects samples, takes field measurements and preserves and transports water, air and soil samples using standard methods for laboratory analysis. Monitoring data is the basis for company reports to regulators and public oversight of pollution, so the role demands solid sampling technique, chain of custody, quality control and absolute honesty."},responsibilities:{vi:["Lập kế hoạch lấy mẫu: vị trí, tần suất, thông số, thiết bị và hóa chất bảo quản.","Lấy mẫu nước thải, nước mặt, khí thải, không khí xung quanh đúng phương pháp tiêu chuẩn.","Đo nhanh tại hiện trường: pH, nhiệt độ, oxy hòa tan, độ dẫn điện, lưu lượng.","Bảo quản, niêm phong, vận chuyển mẫu và ghi phiếu chuỗi hành trình mẫu.","Thực hiện mẫu kiểm soát chất lượng hiện trường: mẫu trắng, mẫu lặp và hiệu chuẩn thiết bị."],en:["Plan sampling: locations, frequency, parameters, equipment and preservatives.","Sample wastewater, surface water, stack emissions and ambient air using standard methods.","Take field measurements: pH, temperature, dissolved oxygen, conductivity and flow.","Preserve, seal and transport samples and complete the chain of custody form.","Run field quality control: blanks, duplicates and instrument calibration."]},competencies:[{name:{vi:"Kỹ thuật lấy mẫu",en:"Sampling technique"},desc:{vi:"Chọn vị trí đại diện, lấy mẫu đơn hoặc mẫu tổ hợp theo lưu lượng đúng phương pháp.",en:"Choose representative points and take grab or flow-proportional composite samples correctly."}},{name:{vi:"Bảo quản & vận chuyển mẫu",en:"Sample preservation & transport"},desc:{vi:"Dùng đúng chai, hóa chất bảo quản, nhiệt độ và thời gian lưu mẫu cho từng thông số.",en:"Use the right container, preservative, temperature and holding time for each parameter."}},{name:{vi:"QA/QC hiện trường",en:"Field QA/QC"},desc:{vi:"Hiệu chuẩn thiết bị, lấy mẫu trắng, mẫu lặp và ghi chép đầy đủ để kết quả được chấp nhận.",en:"Calibrate instruments, take blanks and duplicates and keep full records so results are accepted."}},{name:{vi:"An toàn hiện trường",en:"Field safety"},desc:{vi:"Nhận diện nguy cơ tại cửa xả, ống khói, không gian hạn chế và dùng đúng bảo hộ.",en:"Recognise hazards at outfalls, stacks and confined spaces and use the right protective equipment."}},{name:{vi:"Trung thực số liệu",en:"Data integrity"},desc:{vi:"Giữ nguyên dữ liệu thô, không loại mẫu theo ý khách hàng và báo cáo mọi áp lực.",en:"Keep raw data unchanged, never drop samples at the client's wish and report any pressure."}}],knowledge:{vi:["Luật Bảo vệ môi trường số 72/2020/QH14 và Nghị định 08/2022/NĐ-CP hướng dẫn thi hành.","Thông tư 10/2021/TT-BTNMT quy định kỹ thuật quan trắc môi trường và quản lý thông tin, dữ liệu quan trắc.","Bộ tiêu chuẩn ISO 5667 về lấy mẫu, bảo quản và xử lý mẫu nước.","ISO/IEC 17025 về năng lực phòng thí nghiệm và điều kiện chứng nhận hoạt động dịch vụ quan trắc môi trường (VIMCERTS).","Các quy chuẩn kỹ thuật quốc gia hiện hành về nước thải, khí thải và chất lượng môi trường xung quanh."],en:["Law on Environmental Protection No. 72/2020/QH14 and implementing Decree 08/2022/ND-CP.","Circular 10/2021/TT-BTNMT on technical rules for environmental monitoring and monitoring data management.","The ISO 5667 series on sampling, preservation and handling of water samples.","ISO/IEC 17025 on laboratory competence and the certification of environmental monitoring services (VIMCERTS).","Current national technical regulations on wastewater, stack emissions and ambient environmental quality."]},tools:["Máy đo đa chỉ tiêu cầm tay (pH, DO, EC)","Thiết bị lấy mẫu tự động theo lưu lượng","Thiết bị đo lưu lượng kênh hở","Thiết bị lấy mẫu khí thải đẳng động","Thùng bảo quản lạnh & bộ hóa chất bảo quản"],kpis:{vi:["Tỷ lệ mẫu đạt yêu cầu tiếp nhận của phòng thí nghiệm (đúng bảo quản, đúng thời gian lưu).","Tỷ lệ mẫu QC hiện trường đạt (mẫu trắng, mẫu lặp).","Số sai sót trong chuỗi hành trình mẫu (mục tiêu bằng 0).","Tỷ lệ chuyến quan trắc hoàn thành đúng kế hoạch."],en:["Share of samples accepted by the laboratory (correct preservation and holding time).","Pass rate of field QC samples (blanks, duplicates).","Chain of custody errors (target zero).","Share of monitoring trips completed on schedule."]},day:[{time:"06:30",vi:"Hiệu chuẩn máy đo pH, DO; chuẩn bị chai, nhãn và hóa chất bảo quản theo kế hoạch.",en:"Calibrate pH and DO meters; prepare bottles, labels and preservatives per the plan."},{time:"08:00",vi:"Đến nhà máy, họp an toàn, xác nhận vị trí lấy mẫu tại cửa xả cuối cùng.",en:"Arrive at the plant, attend the safety briefing and confirm the final outfall sampling point."},{time:"09:00",vi:"Lấy mẫu đơn theo giờ, đo nhanh tại chỗ và ghi lưu lượng từng thời điểm.",en:"Take hourly grab samples, measure on site and record the flow at each time."},{time:"13:30",vi:"Lấy mẫu khí thải ống khói lò hơi theo phương pháp đẳng động.",en:"Sample boiler stack emissions using the isokinetic method."},{time:"16:00",vi:"Niêm phong mẫu, bàn giao phòng thí nghiệm kèm phiếu chuỗi hành trình mẫu.",en:"Seal samples and hand them to the laboratory with the chain of custody form."}],mistakes:{vi:["Dùng sai hóa chất bảo quản hoặc để mẫu quá thời gian lưu cho phép.","Lấy trung bình cộng các mẫu đơn khi lưu lượng thay đổi mạnh trong ca.","Lấy mẫu ở vị trí không đại diện, ví dụ sau điểm pha loãng hoặc vùng nước tù."],en:["Using the wrong preservative or exceeding the allowed holding time.","Averaging grab samples arithmetically when flow changes sharply during the shift.","Sampling at an unrepresentative point, such as after dilution or in stagnant water."]},career:[{vi:"Kỹ thuật viên lấy mẫu",en:"Sampling technician"},{vi:"Kỹ thuật viên quan trắc chính",en:"Senior monitoring technician"},{vi:"Trưởng nhóm quan trắc hiện trường",en:"Field monitoring team lead"},{vi:"Quản lý kỹ thuật phòng thí nghiệm môi trường",en:"Environmental laboratory technical manager"}],glossary:[{term:"Grab sample",vi:"Mẫu đơn: mẫu lấy tại một thời điểm, phản ánh chất lượng nước ngay lúc lấy.",en:"A single sample taken at one moment, showing quality at that time."},{term:"Composite sample",vi:"Mẫu tổ hợp: trộn nhiều mẫu đơn theo thời gian hoặc theo tỷ lệ lưu lượng.",en:"A mix of several grab samples combined by time or in proportion to flow."},{term:"Chain of custody",vi:"Chuỗi hành trình mẫu: hồ sơ ghi mọi lần chuyển giao mẫu từ lúc lấy đến lúc phân tích.",en:"Record of every handover of a sample from collection to analysis."},{term:"Field blank",vi:"Mẫu trắng hiện trường: nước sạch đi cùng quy trình lấy mẫu để phát hiện nhiễm bẩn.",en:"Clean water taken through the sampling process to detect contamination."},{term:"COD",vi:"Nhu cầu oxy hóa học: lượng oxy cần để oxy hóa chất hữu cơ trong nước, đơn vị mg/L.",en:"Chemical oxygen demand: oxygen needed to oxidise organic matter in water, in mg/L."}],quiz:[{q:{vi:"Mẫu phân tích kim loại nặng trong nước thường được bảo quản bằng cách nào?",en:"How are water samples for heavy metals usually preserved?"},options:{vi:["Thêm NaOH đến pH lớn hơn 12","Axit hóa bằng HNO3 đến pH nhỏ hơn 2","Thêm H2SO4 đến pH nhỏ hơn 2","Không cần bảo quản"],en:["Add NaOH to pH above 12","Acidify with HNO3 to pH below 2","Add H2SO4 to pH below 2","No preservation needed"]},answer:1,explain:{vi:"Axit nitric giữ kim loại ở dạng hòa tan; axit sunfuric có thể tạo kết tủa với chì, bari.",en:"Nitric acid keeps metals dissolved; sulphuric acid can precipitate lead and barium."}},{q:{vi:"Hai mẫu COD 100 mg/L (lưu lượng 30 m3/h) và 200 mg/L (lưu lượng 70 m3/h). COD trung bình theo lưu lượng là bao nhiêu?",en:"Two COD samples: 100 mg/L at 30 m3/h and 200 mg/L at 70 m3/h. What is the flow-weighted COD?"},options:{vi:["150 mg/L","130 mg/L","185 mg/L","170 mg/L"],en:["150 mg/L","130 mg/L","185 mg/L","170 mg/L"]},answer:3,explain:{vi:"COD theo lưu lượng = (100 x 30 + 200 x 70) / (30 + 70) = 17000 / 100 = 170 mg/L.",en:"(100 x 30 + 200 x 70) / (30 + 70) = 17000 / 100 = 170 mg/L."}},{q:{vi:"Khách hàng đề nghị bỏ một mẫu vượt chuẩn khỏi phiếu kết quả. Bạn làm gì?",en:"The client asks you to remove a non-compliant sample from the result sheet. What do you do?"},options:{vi:["Giữ đủ dữ liệu, báo trưởng phòng và lưu bằng chứng","Bỏ mẫu vì khách hàng trả tiền","Lấy mẫu khác lúc nước sạch hơn để thay","Ghi kết quả nhưng không ký"],en:["Keep all data, inform the manager and keep evidence","Drop the sample because the client pays","Replace it with a cleaner sample","Record it but leave it unsigned"]},answer:0,explain:{vi:"Loại bỏ hay thay mẫu hợp lệ là làm sai lệch số liệu quan trắc, vi phạm pháp luật và nguyên tắc ISO/IEC 17025.",en:"Removing or swapping a valid sample falsifies monitoring data, breaking the law and ISO/IEC 17025 principles."}},{q:{vi:"Mẫu trắng hiện trường dùng để làm gì?",en:"What is a field blank used for?"},options:{vi:["Hiệu chuẩn máy đo pH","Tăng số lượng mẫu","Phát hiện nhiễm bẩn trong quá trình lấy, vận chuyển mẫu","Thay thế mẫu lặp"],en:["Calibrating the pH meter","Increasing the sample count","Detecting contamination during sampling and transport","Replacing duplicates"]},answer:2,explain:{vi:"Nếu mẫu trắng có chất cần phân tích, quy trình lấy mẫu hoặc vận chuyển đã bị nhiễm bẩn.",en:"If the blank contains the analyte, the sampling or transport process was contaminated."}}],tools_en:["Portable multiparameter meter (pH, DO, EC)","Flow-proportional automatic sampler","Open channel flow meter","Isokinetic stack sampling equipment","Cooler box & preservative chemical kit"]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(12)})(window.KKR);
